window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[66]={"id":"066","numero":66,"titre":"Trouble dépressif, anxieux, adaptatif, TSPT, TOC","objectifs":[{"id":"66-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un épisode dépressif caractérisé, d’un trouble dépressif récurrent","contenu":"<p>L’<strong><span class=\"kw-def\">épisode dépressif caractérisé</span></strong> (EDC) associe une <span class=\"kw-clinique\">diminution pathologique de l’humeur</span> (tristesse pathologique) et une <span class=\"kw-clinique\">baisse d’énergie</span>, avec des perturbations <span class=\"kw-clinique\">psychoaffectives</span>, <span class=\"kw-clinique\">psychomotrices</span> et <span class=\"kw-clinique\">physiologiques</span>. Il est associé à un <span class=\"kw-alerte\">risque élevé de suicide</span>.</p>\n      <p>Le terme « <span class=\"kw-def\">dépression</span> » correspond, dans le <span class=\"kw-def\">DSM-5</span>, à l’<span class=\"kw-def\">épisode dépressif caractérisé</span> (anciennement « épisode dépressif majeur » — terminologie modifiée pour éviter la <span class=\"kw-clinique\">confusion</span> avec les critères de sévérité : léger, moyen, sévère).</p>\n      <p><strong>Le diagnostic d’EDC tient compte de trois éléments</strong> : épisode isolé ou récurrence ; sévérité de l’épisode actuel ; existence de caractéristiques cliniques particulières.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">EDC isolé</span></td><td>Un <strong>unique</strong> <span class=\"kw-def\">épisode dépressif caractérisé</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble dépressif récurrent</span></td><td>Présence de <span class=\"kw-chiffre\">≥ 2 EDC</span>, <strong>sans</strong> antécédent d’épisode (hypo)maniaque, séparés par une période sans symptômes de <span class=\"kw-chiffre\">≥ 2 mois</span> consécutifs</td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble bipolaire</span></td><td>EDC parfois appelé « <span class=\"kw-def\">dépression</span> bipolaire » (antécédent d’épisode hypomaniaque ou maniaque)</td></tr>\n          <tr><td>EDC comorbide</td><td>Comorbide de tout autre trouble psychiatrique (anxieux, addictif, <span class=\"kw-etio\">schizophrénie</span>) ou non psychiatrique</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":1},{"id":"66-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<p>L’<span class=\"kw-def\">épisode dépressif caractérisé</span> est un trouble <strong>fréquent</strong>.</p>\n      <ul>\n        <li>Prévalence d’environ <span class=\"kw-chiffre\">10 %</span> chez les <span class=\"kw-chiffre\">18-75 ans</span> en France.</li>\n        <li>Prévalence vie entière chez la femme : <span class=\"kw-chiffre\">22 %</span>.</li>\n        <li><strong>Prédominance féminine</strong> : sex-ratio <span class=\"kw-chiffre\">1,5 à 3 femmes pour 1 homme</span> à partir de l’adolescence (≈ 2F/1H).</li>\n        <li>Âge de début : possible à tout âge, mais plus fréquent chez l’<strong>adulte jeune</strong>, médiane d’âge de début à <span class=\"kw-chiffre\">25 ans</span>.</li>\n      </ul>\n      <p>Conséquences sociétales majeures : coûts directs et indirects conséquents, haut niveau de handicap — l’EDC est la <strong>1ʳᵉ cause d’années de vie perdues en bonne santé dans le monde</strong>.</p>","frequence":1},{"id":"66-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution","contenu":"<p>L’EDC survient <strong>indépendamment de l’ethnie et du niveau d’éducation</strong>. Les <span class=\"kw-etio\">facteurs de risque</span> les plus fréquents :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Faible niveau socio-économique</span>.</li>\n        <li><span class=\"kw-etio\">Expériences traumatiques dans l’enfance</span>.</li>\n        <li><span class=\"kw-etio\">Antécédents personnels</span> d’EDC ; <span class=\"kw-etio\">antécédents familiaux</span> de troubles dépressifs récurrents.</li>\n        <li>Troubles psychiatriques et pathologies non psychiatriques associés.</li>\n      </ul>\n      <p><strong>Évolution</strong> sur la vie entière :</p>\n      <table >\n        <thead><tr><th>Évolution</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td>Un seul EDC sur la vie</td><td><span class=\"kw-chiffre\">50 %</span></td></tr>\n          <tr><td>Récurrence d’épisodes</td><td><span class=\"kw-chiffre\">35 %</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Chronicité</span> (épisode &gt;<span class=\"kw-chiffre\"> 2 ans</span>)</td><td><span class=\"kw-chiffre\">15 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais pronostic</strong> (rechutes / récurrences) : sexe <strong>féminin</strong>, âge de début <strong>précoce</strong>, histoire familiale de trouble de l’humeur, comorbidité psychiatrique ou non ; durée et sévérité plus importantes de l’épisode index, <span class=\"kw-alerte\">syndrome de Cotard</span> ; nombre d’épisodes passés, <span class=\"kw-clinique\">persistance de symptômes résiduels</span> dépressifs.</p>\n      <div class=\"callout callout-info\"><strong>Résistance.</strong> Échec de <span class=\"kw-chiffre\">2 traitements antidépresseurs</span> bien conduits en posologie et en durée.</div>","frequence":1},{"id":"66-4","rang":"B","rubrique":"Étiologie","titre":"Savoir que l’étiologie est multifactorielle","contenu":"<p>L’<span class=\"kw-def\">épisode dépressif caractérisé</span> est <strong>multifactoriel</strong>, mêlant des <span class=\"kw-etio\">facteurs de risque génétiques</span> et <span class=\"kw-etio\">environnementaux</span>.</p>\n      <p>Des déséquilibres de plusieurs systèmes biologiques sont observés :</p>\n      <ul>\n        <li>Neurotransmission <span class=\"kw-etio\">monoaminergique</span> : <span class=\"kw-bio\">sérotonine</span>, <span class=\"kw-bio\">noradrénaline</span>, <span class=\"kw-bio\">dopamine</span>.</li>\n        <li>Axe <span class=\"kw-etio\">corticotrope</span>.</li>\n        <li><span class=\"kw-bio\">Biomarqueurs inflammatoires</span>.</li>\n        <li><span class=\"kw-etio\">Neurotrophines</span> (BDNF).</li>\n        <li>Boucles <span class=\"kw-etio\">fronto-sous-corticales</span>.</li>\n      </ul>","frequence":0},{"id":"66-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie du syndrome dépressif","contenu":"<p>Le <strong><span class=\"kw-def\">syndrome dépressif</span></strong> est caractérisé par la persistance dans le temps (<span class=\"kw-chiffre\">≥ 15 jours</span>) d’une <span class=\"kw-clinique\">tristesse pathologique de l’humeur</span> et d’une <span class=\"kw-clinique\">baisse d’énergie</span>. Il associe une constellation de signes répartis en trois familles.</p>\n      <p><strong>1 · Perturbations psychoaffectives</strong></p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td>Humeur</td><td><span class=\"kw-clinique\">Humeur dépressive / triste</span>, sentiment pénible et envahissant ; quasi constante, indépendante des circonstances ; prédomine <strong>le matin dès le réveil</strong>, tend à s’améliorer dans la journée</td></tr>\n          <tr><td>Émotions</td><td><span class=\"kw-clinique\">Anhédonie</span> (perte du plaisir, presque toujours présente) ; <span class=\"kw-clinique\">anesthésie affective</span> (émoussement émotionnel) ; <span class=\"kw-clinique\">anxiété</span> ; <span class=\"kw-clinique\">irritabilité</span> (surtout chez l’adolescent)</td></tr>\n          <tr><td>Contenu de la pensée</td><td><span class=\"kw-clinique\">Idées de culpabilité</span> / auto-accusation ; <span class=\"kw-clinique\">idées de dévalorisation</span> (perte d’estime de soi) ; <span class=\"kw-clinique\">idées d’incurabilité</span></td></tr>\n          <tr><td>Pensées de mort</td><td>Pensées centrées sur la mort ; <span class=\"kw-alerte\">idées suicidaires</span> avec ou sans plan précis</td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 · Perturbations psychomotrices</strong> — ralentissement ou agitation peuvent alterner ou s’associer.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td>Cours de la pensée</td><td><span class=\"kw-clinique\">Bradypsychie</span> (ralentissement des idées) ; <span class=\"kw-clinique\">ruminations</span> ; <span class=\"kw-clinique\">monoïdéisme</span></td></tr>\n          <tr><td>Cognition</td><td>Altérations de la <span class=\"kw-clinique\">concentration</span>, de la <span class=\"kw-clinique\">mémoire</span>, de l’<span class=\"kw-clinique\">attention</span> ; <span class=\"kw-clinique\">indécision</span></td></tr>\n          <tr><td>Ralentissement moteur</td><td><span class=\"kw-clinique\">Bradykinésie</span> ; <span class=\"kw-clinique\">hypomimie</span> voire amimie ; <span class=\"kw-clinique\">bradyphémie</span> ; voix monocorde (aprosodie) ; <span class=\"kw-clinique\">clinophilie</span> ; <span class=\"kw-clinique\">incurie</span> ; <span class=\"kw-clinique\">aboulie</span></td></tr>\n          <tr><td>Agitation</td><td><span class=\"kw-clinique\">Déambulations permanentes</span>, incapacité à s’asseoir ; souvent liée à une tension interne et une anxiété accrue</td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · Perturbations physiologiques</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Insomnie</span> fréquente (réveils nocturnes, réveils précoces, difficultés d’endormissement) ; <span class=\"kw-clinique\">somnolence</span> possible.</li>\n        <li><span class=\"kw-clinique\">Fatigue</span> et <span class=\"kw-clinique\">perte d’énergie</span> / <span class=\"kw-clinique\">asthénie</span> permanente.</li>\n        <li>Perturbations alimentaires : <span class=\"kw-clinique\">anorexie</span> le plus souvent, parfois hyperphagie ; variations de poids.</li>\n        <li><span class=\"kw-clinique\">Hyposexualité</span> (diminution du désir et de l’excitation).</li>\n        <li>Symptômes neurovégétatifs, digestifs, douloureux divers.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Distinction utile.</strong> <span class=\"kw-clinique\">Aboulie</span> = incapacité à exécuter des actes pourtant planifiés ≠ <span class=\"kw-clinique\">apragmatisme</span> = incapacité à entreprendre par défaut de planification.</div>","frequence":10},{"id":"66-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques chez l’enfant et l’adolescent","contenu":"<p>Les <strong>critères diagnostiques restent identiques à ceux de l’adulte</strong>, mais l’expression clinique diffère.</p>\n      <ul>\n        <li>Les perturbations de l’humeur peuvent ne pas se manifester par de la tristesse mais par : <span class=\"kw-clinique\">crises de colère</span> plus fréquentes (notamment chez les TSA) ; <span class=\"kw-clinique\">irritabilité épisodique</span> (notamment chez les TDAH).</li>\n        <li>L’<strong>irritabilité chronique</strong> doit être distinguée de l’irritabilité épisodique : elle évoque une dérégulation émotionnelle sévère de l’enfant (crises de colère répétées + irritabilité persistante entre les crises).</li>\n        <li><span class=\"kw-clinique\">Altération des performances ou du rendement scolaire</span> fréquente.</li>\n        <li>Les courbes staturo-pondérales permettent d’objectiver les modifications du poids.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>À retenir.</strong> Plus le <strong>1ᵉʳ épisode est précoce</strong>, plus le risque de <span class=\"kw-alerte\">récidive</span> et le <span class=\"kw-alerte\">risque suicidaire</span> sont élevés.</div>","frequence":5},{"id":"66-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques chez la personne âgée","contenu":"<p>Chez la personne âgée, la souffrance psychique (et notamment la tristesse) est souvent peu exprimée ; les plaintes sont volontiers d’allure non psychiatrique (algiques, mnésiques). Plusieurs présentations particulières :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Présentation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dépression masquée</span></td><td><span class=\"kw-clinique\">Plaintes somatiques</span> au premier plan (<span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">douleurs abdominales</span>, oppression thoracique, douleurs musculo-squelettiques) ; tristesse non exprimée</td></tr>\n          <tr><td><span class=\"kw-def\">Dépression hostile</span></td><td>Anxiété, récriminations, <span class=\"kw-clinique\">agitation hostile</span>, refus de soins, agressivité dirigée contre l’entourage ; modification récente du comportement</td></tr>\n          <tr><td><span class=\"kw-def\">Dépression avec plainte mnésique</span></td><td>La <span class=\"kw-clinique\">plainte mnésique</span> est un symptôme dépressif chez le sujet âgé — diagnostic différentiel important avec le trouble neurocognitif</td></tr>\n          <tr><td><span class=\"kw-alerte\">Dépression sévère</span></td><td>Forme <strong>mélancolique</strong> (prostration, mutisme, refus de manger ou de traitement) ou <strong>délirante</strong> (idées d’incurabilité, de ruine, de négation d’organe — <span class=\"kw-alerte\">syndrome de Cotard</span>) ; PEC spécialisée, souvent en hospitalisation</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"66-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères DSM-5 de l’épisode dépressif caractérisé, les critères DSM-5 du trouble dépressif récurrent","contenu":"<p><strong>Les 9 symptômes du critère A</strong> (ne pas inclure les symptômes manifestement imputables à une affection générale) :</p>\n      <ol>\n        <li><span class=\"kw-clinique\">Humeur dépressive</span> présente quasiment toute la journée, presque tous les jours.</li>\n        <li><span class=\"kw-clinique\">Diminution de l’intérêt ou du plaisir</span> pour presque toutes les activités.</li>\n        <li>Perte ou gain de poids significatif (<span class=\"kw-chiffre\">5 %</span>) ou modification de l’appétit.</li>\n        <li><span class=\"kw-clinique\">Insomnie</span> ou hypersomnie presque tous les jours.</li>\n        <li><span class=\"kw-clinique\">Agitation</span> ou <span class=\"kw-clinique\">ralentissement psychomoteur</span>.</li>\n        <li><span class=\"kw-clinique\">Fatigue</span> ou perte d’énergie.</li>\n        <li>Sentiment de <span class=\"kw-clinique\">dévalorisation</span> ou de <span class=\"kw-clinique\">culpabilité</span> excessive.</li>\n        <li>Diminution de l’aptitude à penser / se concentrer, ou <span class=\"kw-clinique\">indécision</span>.</li>\n        <li><span class=\"kw-alerte\">Pensées de mort</span> récurrentes, <span class=\"kw-alerte\">idées suicidaires</span>.</li>\n      </ol>\n      <table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td><span class=\"kw-chiffre\">≥ 5/9 symptômes</span> pendant <span class=\"kw-chiffre\">≥ 2 semaines</span>, représentant un changement par rapport à l’état antérieur, avec <span class=\"kw-chiffre\">≥ 1</span> symptôme = humeur dépressive <strong>ou</strong> perte d’intérêt / de plaisir</td></tr>\n          <tr><td>B</td><td>Détresse cliniquement significative ou <span class=\"kw-clinique\">altération du fonctionnement</span> social, professionnel ou autre</td></tr>\n          <tr><td>C</td><td>Non imputable à une <span class=\"kw-etio\">substance</span> ou une affection médicale générale</td></tr>\n          <tr><td>D</td><td>Ne répond pas aux critères d’un trouble schizo-affectif et ne se superpose pas à une <span class=\"kw-etio\">schizophrénie</span> ou à un autre trouble psychotique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Sévérité</strong> : <span class=\"kw-def\">léger</span> (symptômes juste suffisants, peu de perturbations) ; <span class=\"kw-def\">moyen</span> (plus de symptômes, perturbations modérées) ; <span class=\"kw-alerte\">sévère</span> (quasiment tous les symptômes, perturbations nettes).</p>\n      <p><strong>Trouble dépressif récurrent</strong> : <span class=\"kw-chiffre\">≥ 2 EDC</span> séparés d’une période sans symptômes de <span class=\"kw-chiffre\">≥ 2 mois</span> consécutifs.</p>\n      <div class=\"callout callout-info\"><strong>Caractéristiques cliniques de l’EDC.</strong> <span class=\"kw-alerte\">Mélancolique</span> (intensité sévère, risque suicidaire élevé, anhédonie / anesthésie affective, réveils matinaux précoces) ; <span class=\"kw-alerte\">psychotique</span> (hallucinations, idées délirantes, syndrome de Cotard) ; <span class=\"kw-alerte\">mixte</span> (≥ 3 symptômes (hypo)maniaques — risque suicidaire très augmenté) ; <span class=\"kw-clinique\">anxieux</span> (raptus anxieux) ; <span class=\"kw-alerte\">catatonique</span> ; atypique.</div>","frequence":4},{"id":"66-9","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir rechercher un antécédent d’épisode maniaque ou hypomaniaque","contenu":"<p>Devant tout épisode dépressif, il faut systématiquement rechercher un antécédent d’<span class=\"kw-def\">épisode maniaque ou hypomaniaque</span> : sa présence fait basculer le diagnostic vers un <strong><span class=\"kw-etio\">trouble bipolaire</span></strong>, dont la prise en charge diffère radicalement. Distinguer un EDC unipolaire d’une « <span class=\"kw-def\">dépression</span> bipolaire » est délicat.</p>\n      <p><strong>Caractéristiques devant faire évoquer un <span class=\"kw-etio\">trouble bipolaire</span> :</strong></p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments d’orientation</th></tr></thead>\n        <tbody>\n          <tr><td>Terrain</td><td>Antécédent <strong>familial</strong> de trouble de l’humeur ; EDC avant <span class=\"kw-chiffre\">25 ans</span></td></tr>\n          <tr><td>Contexte</td><td>EDC en <span class=\"kw-clinique\">post-partum</span> ; antécédents d’EDC multiples (<span class=\"kw-chiffre\">≥ 3</span>)</td></tr>\n          <tr><td>Épisode</td><td>Début <strong>brutal</strong> ; caractéristiques mélancoliques ou saisonnières</td></tr>\n          <tr><td>Réponse au traitement</td><td><span class=\"kw-alerte\">Non-réponse voire aggravation</span> sous antidépresseur ; apparition d’une <span class=\"kw-alerte\">agitation</span> ou d’une <span class=\"kw-alerte\">hypomanie</span>, même brève</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":1},{"id":"66-10","rang":"B","rubrique":"Diagnostic différentiel","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<p>Comme pour tout trouble psychiatrique, une <strong>étiologie non psychiatrique doit être éliminée</strong> avant de retenir le diagnostic d’EDC.</p>\n      <table >\n        <thead><tr><th>Non psychiatriques</th><th>Psychiatriques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Substances :</strong> <span class=\"kw-etio\">substances psychoactives</span> (DD le plus fréquent)<br>\n              <strong>Neurologiques :</strong> tumeur cérébrale ; SEP ; <span class=\"kw-etio\">AVC</span> ; pathologie neuro-dégénérative (surtout si épisode &gt; <span class=\"kw-chiffre\">40 ans</span>) ; <span class=\"kw-etio\">épilepsie</span> focale<br>\n              <strong>Endocriniennes :</strong> dysthyroïdies ; maladie de Cushing<br>\n              <strong>Métaboliques :</strong> hypoglycémie ; troubles ioniques ; maladie de Wilson<br>\n              <strong>Iatrogènes :</strong> <span class=\"kw-ci\">corticoïdes</span> ; <span class=\"kw-ci\">interféron alpha</span> ; <span class=\"kw-ci\">bêta-bloquants</span> ; <span class=\"kw-ci\">L-DOPA</span>\n            </td>\n            <td>\n              Autres troubles de l’humeur<br>\n              Trouble de la personnalité<br>\n              TDAH<br>\n              <span class=\"kw-etio\">Schizophrénie</span><br>\n              Troubles anxieux ; TOC<br>\n              Trouble délirant persistant<br>\n              Troubles addictifs\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant</em></p>","frequence":1},{"id":"66-11","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier le risque suicidaire","contenu":"<p>L’<span class=\"kw-def\">épisode dépressif caractérisé</span> est associé à un <span class=\"kw-alerte\">risque suicidaire élevé</span> — son évaluation est <strong>systématique</strong> à chaque consultation.</p>\n      <ul>\n        <li>Environ <span class=\"kw-chiffre\">30 à 50 %</span> des tentatives de suicide en France sont secondaires à un EDC.</li>\n        <li>Plus de <span class=\"kw-chiffre\">80 %</span> des personnes décédées par suicide présentaient un EDC au moment du passage à l’acte.</li>\n      </ul>\n      <p>Rechercher activement les <span class=\"kw-alerte\">pensées de mort</span>, les <span class=\"kw-alerte\">idées suicidaires</span> (avec ou sans plan précis), un antécédent de tentative de suicide.</p>\n      <div class=\"callout callout-danger\"><strong>Urgence.</strong> Le risque de passage à l’acte est majeur dans les formes <span class=\"kw-alerte\">mélancolique</span>, <span class=\"kw-alerte\">mixte</span> et <span class=\"kw-alerte\">anxieuse</span> (raptus anxieux). Un risque suicidaire élevé impose une <strong>hospitalisation</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p>","frequence":4},{"id":"66-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications d’un bilan complémentaire devant un syndrome dépressif","contenu":"<p>Le diagnostic d’EDC est <strong>clinique</strong>. Un bilan complémentaire est indiqué pour <strong>éliminer une étiologie non psychiatrique</strong> (diagnostic différentiel) avant de retenir le diagnostic.</p>\n      <ul>\n        <li>Recherche d’une cause <span class=\"kw-etio\">endocrinienne</span>, <span class=\"kw-etio\">métabolique</span>, <span class=\"kw-etio\">neurologique</span> ou <span class=\"kw-etio\">toxique</span>.</li>\n        <li>Examens orientés par les <strong>points d’appel cliniques</strong> de l’interrogatoire et de l’examen.</li>\n        <li>Une <span class=\"kw-imagerie\">imagerie cérébrale</span> est notamment justifiée devant un 1ᵉʳ épisode chez un patient de plus de <span class=\"kw-chiffre\">40 ans</span>.</li>\n      </ul>","frequence":1},{"id":"66-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires devant un syndrome dépressif","contenu":"<table >\n        <thead><tr><th>Bilan</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Bilan sanguin</td><td><span class=\"kw-bio\">Glycémie</span> capillaire ou veineuse ; <span class=\"kw-bio\">ionogramme</span> et <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">bilan rénal</span> (<span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatininémie</span>) ; <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">TSHus</span> ; <span class=\"kw-bio\">bilan hépatique</span></td></tr>\n          <tr><td>Bilan urinaire</td><td><span class=\"kw-bio\">Toxiques urinaires</span> : cannabis, cocaïne, <span class=\"kw-ttt\">opiacés</span>, amphétamines</td></tr>\n          <tr><td>Autres</td><td>Selon les points d’appel : <span class=\"kw-bio\">IRM cérébrale</span>, <span class=\"kw-bio\">EEG</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"66-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications du recours au psychiatre","contenu":"<p>Un <strong>recours au psychiatre</strong> est indiqué devant un EDC dans les situations suivantes :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Comorbidités</span> psychiatriques ou non psychiatriques.</li>\n        <li>Épisode avec <span class=\"kw-alerte\">résistance</span> à 2 antidépresseurs bien conduits (posologie et durée suffisantes).</li>\n        <li>Situations à risque : grossesse, post-partum.</li>\n        <li>Caractéristiques cliniques particulières ou doute sur un <span class=\"kw-etio\">trouble bipolaire</span>.</li>\n      </ul>\n      <p>En cas de prise en charge ambulatoire : <strong>consultations rapprochées et régulières</strong> (≈ <span class=\"kw-chiffre\">1 fois/semaine</span>).</p>","frequence":1},{"id":"66-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications d’hospitalisation en psychiatrie","contenu":"<p>L’<strong>hospitalisation en psychiatrie</strong> devant un EDC est indiquée si :</p>\n      <ul>\n        <li>Caractéristiques cliniques spécifiques : <span class=\"kw-alerte\">mélancolique</span>, <span class=\"kw-alerte\">psychotique</span>, <span class=\"kw-alerte\">mixte</span>, <span class=\"kw-alerte\">catatonique</span>.</li>\n        <li><span class=\"kw-alerte\">Risque suicidaire élevé</span> ou risque de mise en danger.</li>\n        <li>Formes sévères et/ou résistantes au traitement, comorbidités complexes.</li>\n      </ul>","frequence":1},{"id":"66-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements non pharmacologiques","contenu":"<p><strong>Psychothérapie</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Psychothérapie de soutien</span> : toujours indiquée.</li>\n        <li><span class=\"kw-ttt\">Psychothérapies structurées</span> : en monothérapie pour les EDC légers, ou en association au traitement médicamenteux pour les EDC modérés à sévères. Les <span class=\"kw-ttt\">TCC</span> et les <span class=\"kw-ttt\">thérapies interpersonnelles</span> ont les niveaux de preuve les plus élevés.</li>\n      </ul>\n      <p><strong>Traitements physiques</strong></p>\n      <table >\n        <thead><tr><th>Technique</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Électroconvulsivothérapie</span> (ECT / sismothérapie)</td><td>Formes <span class=\"kw-alerte\">mélancolique</span>, <span class=\"kw-alerte\">catatonique</span> ou <span class=\"kw-alerte\">psychotique</span> ; résistance ou <span class=\"kw-ci\">contre-indication</span> au traitement médicamenteux ; urgence vitale (risque suicidaire, dénutrition, <span class=\"kw-clinique\">déshydratation</span>) ; ECT d’entretien (≈ 1 fois/mois) pour prévenir les rechutes</td></tr>\n          <tr><td><span class=\"kw-ttt\">Stimulation magnétique transcrânienne</span> (rTMS)</td><td>Méthode non invasive, utilisée dans des situations particulières (en cours d’évaluation pour l’EDC)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Pour l’ECT, l’<span class=\"kw-ci\">HTIC</span> est la <strong>seule <span class=\"kw-ci\">contre-indication</span> absolue</strong>. Les autres (troubles de l’hémostase, du rythme, <span class=\"kw-etio\">épilepsie</span>, <span class=\"kw-etio\">ostéoporose</span> sévère) sont relatives.</div>","frequence":4},{"id":"66-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques","contenu":"<p><strong>Antidépresseur</strong></p>\n      <ul>\n        <li>Indication : EDC d’intensité <strong>modérée à sévère</strong>.</li>\n        <li>1ʳᵉ intention : <span class=\"kw-ttt\">ISRS</span>, augmenté progressivement à posologie efficace selon la tolérance.</li>\n        <li>Délai d’action : réponse en <span class=\"kw-chiffre\">≥ 2 à 4 semaines</span> à dose efficace.</li>\n        <li>En cas d’échec : augmenter les posologies ou <strong>changer</strong> d’antidépresseur — <span class=\"kw-ci\">ne pas associer 2 antidépresseurs</span>.</li>\n        <li>Durée pour un 1ᵉʳ EDC isolé : arrêt discuté <span class=\"kw-chiffre\">6 mois à 1 an</span> après la rémission ; <strong>risque maximal de rechute à<span class=\"kw-chiffre\"> 6-8 mois</span></strong> après l’arrêt.</li>\n      </ul>\n      <p><strong>Traitements associés</strong> selon les caractéristiques : <span class=\"kw-ttt\">antipsychotique</span> si caractéristiques psychotiques ; <span class=\"kw-ttt\">benzodiazépine</span> si anxiété importante en début de traitement ; <span class=\"kw-ttt\">hypnotique</span> si insomnie.</p>\n      <p><strong>Résistance</strong> : échec de <span class=\"kw-chiffre\">2 antidépresseurs</span> à dose efficace pendant une durée suffisante (<span class=\"kw-chiffre\">≥ 6 semaines</span>).</p>\n      <p><strong>Trouble dépressif récurrent</strong> (dès le 3ᵉ épisode) : traitement de maintien par antidépresseur (molécule et posologie ayant permis la rémission) ; psychothérapie associée pendant <span class=\"kw-chiffre\">18 mois à 2 ans</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":4,"liens":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/inhibiteurs-selectifs-de-la-recapture-de-la-serotonine-isrs","label":"Pharmacomedicale — ISRS (inhibiteurs sélectifs de la recapture de la sérotonine)"}]},{"id":"66-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques chez l’enfant et l’adolescent","contenu":"<table >\n        <thead><tr><th>Population</th><th>Stratégie</th></tr></thead>\n        <tbody>\n          <tr><td>Enfant / adolescent</td><td>Intensité <strong>légère à modérée</strong> → traitement non pharmacologique en 1ʳᵉ intention. Intensité <strong>modérée à sévère</strong> → traitement pharmacologique (<span class=\"kw-ttt\">fluoxétine</span> en 1ʳᵉ intention, autres <span class=\"kw-ttt\">ISRS</span> en 2ᵉ intention, durée <span class=\"kw-chiffre\">≥ 6 mois</span>) + traitement non pharmacologique</td></tr>\n          <tr><td>Personne âgée</td><td>Légère à modérée → non pharmacologique en 1ʳᵉ intention. Modérée à sévère → <span class=\"kw-ttt\">ISRS</span> en 1ʳᵉ intention</td></tr>\n          <tr><td>Femme enceinte</td><td>Le rapport bénéfice-risque du traitement antidépresseur est discuté individuellement</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"66-19","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un trouble anxiété généralisée, d’un trouble panique, d’une agoraphobie, d’un trouble anxiété sociale, des phobies spécifiques, d’une anxiété de séparation, d’un refus scolaire anxieux","contenu":"<p>Les <span class=\"kw-def\">troubles anxieux</span> correspondent à des manifestations anxieuses pathologiques par leur intensité, leur retentissement et leur mauvais contrôle, constituant un <strong>diagnostic spécifique</strong> (≠ symptôme anxieux présent dans presque tous les troubles psychiatriques).</p>\n      <table >\n        <thead><tr><th>Trouble</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Trouble anxieux généralisé</span> (TAG)</td><td>Soucis excessifs et mal contrôlés, chroniques, évoluant <span class=\"kw-chiffre\">&gt; 6 mois</span> — « maladie des inquiétudes »</td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble panique</span></td><td>Répétition d’<span class=\"kw-clinique\">attaques de panique</span> + <span class=\"kw-clinique\">anxiété anticipatoire</span> de leur survenue</td></tr>\n          <tr><td><span class=\"kw-etio\">Agoraphobie</span></td><td>Crainte / évitement des situations où il serait difficile de s’échapper ou de trouver du secours en cas de symptômes de panique</td></tr>\n          <tr><td><span class=\"kw-etio\">Anxiété sociale</span> (phobie sociale)</td><td>Crainte d’agir de façon embarrassante ou humiliante sous le regard et le jugement d’autrui</td></tr>\n          <tr><td><span class=\"kw-etio\">Phobie spécifique</span></td><td>Peur intense, irraisonnée et incontrôlable d’un objet ou d’une situation bien définie</td></tr>\n          <tr><td><span class=\"kw-etio\">Anxiété de séparation</span></td><td>Inquiétudes excessives concernant la perte des figures d’attachement ou la séparation d’avec elles</td></tr>\n          <tr><td><span class=\"kw-etio\">Refus scolaire anxieux</span></td><td>Manifestation d’un trouble anxieux chez l’enfant / l’adolescent, avec retentissement sur la scolarité</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Logique discriminante.</strong> Phobie spécifique = objet précis ; trouble panique ± agoraphobie = anticipation d’une nouvelle attaque ; phobie sociale = jugement d’autrui ; TOC = obsessions / compulsions ; TAG = soucis multiples et permanents ; TSPT = reviviscence d’un traumatisme.</div>","frequence":4},{"id":"66-20","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence des principaux troubles, l’âge de début des troubles","contenu":"<table >\n        <thead><tr><th>Trouble</th><th>Prévalence</th><th>Âge de début</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">TAG</span></td><td><span class=\"kw-chiffre\">5 %</span> en population générale ; prédominance féminine (<span class=\"kw-chiffre\">2F/1H</span>)</td><td>Tout âge, le plus souvent <span class=\"kw-chiffre\">35-45 ans</span> ; trouble anxieux le plus fréquent chez le sujet âgé</td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble panique</span></td><td><span class=\"kw-chiffre\">1-3 %</span> ; prédominance féminine</td><td>Typiquement <span class=\"kw-chiffre\">20-30 ans</span> ; débuts précoces possibles (enfance, adolescence)</td></tr>\n          <tr><td><span class=\"kw-etio\">Phobie spécifique</span></td><td><span class=\"kw-chiffre\">10-12 %</span> sur la vie ; <span class=\"kw-chiffre\">&gt; 20 %</span> chez l’enfant</td><td>Enfance ou début d’adolescence</td></tr>\n          <tr><td><span class=\"kw-etio\">Phobie sociale</span></td><td><span class=\"kw-chiffre\">≈ 5 %</span> sur la vie</td><td>Entre <span class=\"kw-chiffre\">10 et 20 ans</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Refus scolaire anxieux</span></td><td><span class=\"kw-chiffre\">1 %</span> des enfants en âge scolaire</td><td>Âge scolaire</td></tr>\n        </tbody>\n      </table>\n      <p>Les troubles phobiques font partie des troubles psychiatriques les plus fréquents.</p>","frequence":1},{"id":"66-21","rang":"B","rubrique":"Étiologie","titre":"Savoir que l’étiologie est multifactorielle","contenu":"<p>L’origine des troubles anxieux est <strong>multifactorielle</strong> : <span class=\"kw-etio\">facteurs de vulnérabilité génétique</span> (tempérament anxieux, sensibilité au stress), <span class=\"kw-etio\">facteurs neurobiologiques</span> et <span class=\"kw-etio\">facteurs environnementaux</span> (pression professionnelle, événements de vie traumatisants, apprentissage social par imitation).</p>\n      <p><strong>Mécanismes cognitifs particuliers :</strong></p>\n      <ul>\n        <li><strong>TAG</strong> : « <span class=\"kw-etio\">intolérance à l’incertitude</span> » ; « <span class=\"kw-etio\">alerte émotionnelle anormale</span> » (attribution d’un caractère dangereux à des stimuli non menaçants).</li>\n        <li><strong>Trouble panique</strong> : « <span class=\"kw-etio\">phobie intéroceptive</span> » — interprétation catastrophiste de sensations internes physiologiques, entretenant un véritable <span class=\"kw-clinique\">cercle vicieux</span>.</li>\n      </ul>","frequence":0},{"id":"66-22","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie des principaux troubles (voir item 64)","contenu":"<p><strong>Trouble anxieux généralisé (TAG)</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Appréhension continue</span> non associée à un événement déclencheur, présente tous les jours ou presque, portant sur <span class=\"kw-chiffre\">≥ 2 thèmes</span> (avenir, santé, travail, argent, proches).</li>\n        <li>Anxiété <strong>difficile à contrôler</strong>, voire non contrôlable, évoluant sur <span class=\"kw-chiffre\">≥ 6 mois</span>.</li>\n        <li>Manifestations associées : <span class=\"kw-clinique\">insomnie</span> souvent au 1ᵉʳ plan, <span class=\"kw-clinique\">irritabilité</span>, <span class=\"kw-clinique\">asthénie</span>, difficultés de concentration, tensions musculaires, <span class=\"kw-clinique\">céphalées</span>.</li>\n      </ul>\n      <p><strong>Trouble panique</strong></p>\n      <ul>\n        <li>Répétition d’<span class=\"kw-clinique\">attaques de panique</span> spontanées et imprévisibles (au moins au début).</li>\n        <li><span class=\"kw-clinique\">Anxiété anticipatoire</span> permanente = « peur d’avoir peur » ; conditionnement interne (les symptômes d’une AP débutante deviennent eux-mêmes angoissants).</li>\n        <li>Conséquences : <span class=\"kw-etio\">isolement social</span>, peur de perdre le contrôle, de devenir fou ou de mourir.</li>\n        <li><span class=\"kw-etio\">Agoraphobie</span> (entité distincte) : peur ou anxiété marquées dans <span class=\"kw-chiffre\">≥ 2/5</span> situations (transports en commun, endroits ouverts, endroits clos, file d’attente / foule, être seul hors du domicile), avec évitement ou nécessité d’un accompagnant.</li>\n      </ul>\n      <p><strong>Phobies</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Phobie spécifique</span> : peur déclenchée par un objet / une situation définie (la simple évocation suffit) ; <span class=\"kw-clinique\">conduites d’évitement</span> et anticipation anxieuse ; principale = <span class=\"kw-clinique\">zoophobie</span>.</li>\n        <li><span class=\"kw-etio\">Phobie sociale</span> : peur des interactions sociales, d’être observé, des situations de performance ; symptômes physiques (<span class=\"kw-clinique\">tachycardie</span>, rougeur, tremblements, <span class=\"kw-clinique\">sueurs</span>) ; évitements multiples + anxiété anticipatoire.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span></em></p>","frequence":13},{"id":"66-23","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités chez l’enfant et l’adolescent","contenu":"<ul>\n        <li><strong>TAG</strong> : inquiétudes centrées sur les performances <span class=\"kw-clinique\">sportives et scolaires</span> ; particulièrement fréquent chez l’enfant présentant un trouble du neurodéveloppement.</li>\n        <li><strong>Phobie spécifique</strong> : s’inscrit le plus souvent dans le développement normal de l’enfant (apparition &lt; <span class=\"kw-chiffre\">8 ans</span> : créatures imaginaires, obscurité, animaux). Pathologique seulement si intensité importante, persistance prolongée et retentissement sur les activités.</li>\n        <li><span class=\"kw-etio\">Refus scolaire anxieux</span> : conséquence de troubles psychiatriques divers et intriqués (anxiété de séparation, phobie sociale, phobie spécifique, trouble panique, trouble de l’humeur), avec répercussions sur les apprentissages.</li>\n        <li><span class=\"kw-etio\">Anxiété de séparation</span> : inquiétudes excessives de perdre ses parents, refus de quitter la maison, cauchemars, plaintes physiques lors des séparations.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège tombé en concours blanc.</strong> Le <span class=\"kw-clinique\">perfectionnisme</span> est fréquemment associé au TAG chez l’enfant et l’adolescent.</div>","frequence":1},{"id":"66-24","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités chez la personne âgée","contenu":"<p>Il n’existe <strong>pas de spécificité sémiologique</strong> du TAG ni des troubles phobiques chez le sujet âgé.</p>\n      <p>À noter cependant que le <span class=\"kw-etio\">TAG</span> est le <strong>trouble anxieux le plus fréquent chez le sujet âgé</strong>.</p>","frequence":0},{"id":"66-25","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques DSM-5","contenu":"<p><strong>Trouble anxieux généralisé</strong></p>\n      <table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td>Anxiété et soucis excessifs, la plupart du temps, durant <span class=\"kw-chiffre\">≥ 6 mois</span></td></tr>\n          <tr><td>B</td><td>Difficulté à contrôler cette préoccupation</td></tr>\n          <tr><td>C</td><td><span class=\"kw-chiffre\">≥ 3/6</span> symptômes : agitation, fatigabilité, difficultés de concentration, irritabilité, tension musculaire, perturbations du sommeil</td></tr>\n          <tr><td>D-F</td><td>Détresse / altération du fonctionnement ; non imputable à une substance ou affection médicale ; non mieux expliqué par un autre trouble mental</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trouble panique</strong> — AP récurrentes et inattendues (critère A), suivies d’une période de <span class=\"kw-chiffre\">≥ 1 mois</span> de crainte d’autres AP ou de changement de comportement inadapté (critère B).</p>\n      <p><strong>Phobie spécifique / phobie sociale</strong> — peur ou anxiété intenses face à l’objet / la situation ou aux situations sociales ; provocation quasi systématique ; évitement actif ; peur <span class=\"kw-clinique\">disproportionnée</span> ; persistance <span class=\"kw-chiffre\">≥ 6 mois</span> ; altération du fonctionnement.</p>\n      <div class=\"callout callout-info\"><strong>Piège tombé en concours blanc.</strong> Connaître les critères DSM-5 de l’<span class=\"kw-etio\">agoraphobie</span> : peur dans <span class=\"kw-chiffre\">≥ 2/5</span> situations, évitement / accompagnant nécessaire, peur disproportionnée, persistance <span class=\"kw-chiffre\">≥ 6 mois</span>.</div>","frequence":4},{"id":"66-26","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<table >\n        <thead><tr><th>Catégorie</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td>Non psychiatriques</td><td><strong>Cardiovasculaires :</strong> <span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">HTA</span>, troubles du rythme<br><strong>Respiratoires :</strong> <span class=\"kw-etio\">asthme</span>, pneumopathie<br><strong>Neurologiques :</strong> <span class=\"kw-etio\">épilepsie</span>, SEP, crises migraineuses, <span class=\"kw-etio\">AIT</span><br><strong>Endocriniens :</strong> hypoglycémie, dysthyroïdie, phéochromocytome, Cushing</td></tr>\n          <tr><td>Substances</td><td>Intoxications (amphétamines, cocaïne, cannabis, hallucinogènes) ; syndromes de <span class=\"kw-etio\">sevrage</span> (<span class=\"kw-etio\">alcool</span>, BZD, <span class=\"kw-ttt\">opiacés</span>)</td></tr>\n          <tr><td>Psychiatriques</td><td>Autres troubles anxieux entre eux ; <span class=\"kw-clinique\">hypochondrie</span> ; <span class=\"kw-def\">épisode dépressif caractérisé</span> (à la fois DD et complication)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant</em></p>","frequence":0},{"id":"66-27","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires et leurs indications","contenu":"<p>Le diagnostic des troubles anxieux est <strong>clinique</strong>. Aucun examen n’est nécessaire au diagnostic positif ; les examens paracliniques, <strong>orientés par les points d’appel</strong> de l’examen physique, servent uniquement à <strong>éliminer un diagnostic différentiel non psychiatrique</strong> ou une prise de substance.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Diagnostic différentiel ciblé</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ECG</span></td><td>Devant des palpitations / douleurs thoraciques : DD <span class=\"kw-clinique\">cardiovasculaire</span> (<span class=\"kw-alerte\">SCA</span>, trouble du rythme, etc.)</td></tr>\n          <tr><td><span class=\"kw-bio\">Glycémie capillaire</span></td><td>DD <span class=\"kw-clinique\">hypoglycémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">TSH</span></td><td>DD <span class=\"kw-clinique\">dysthyroïdie</span> (notamment hyperthyroïdie)</td></tr>\n          <tr><td><span class=\"kw-bio\">Recherche de toxiques</span></td><td>Intoxication par une <span class=\"kw-etio\">substance psychoactive</span> ou syndrome de <span class=\"kw-etio\">sevrage</span> (alcool, BZD…), selon le contexte</td></tr>\n        </tbody>\n      </table>\n      <p>Autres examens (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">troponine</span>, imagerie…) seulement <strong>selon les points d’appel</strong> cliniques (cardiovasculaire, respiratoire, neurologique, endocrinien).</p>","frequence":1},{"id":"66-28","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications du recours au psychiatre","contenu":"<p>Le <strong>recours au psychiatre</strong> devant un trouble anxieux est indiqué si :</p>\n      <ul>\n        <li>Trouble <span class=\"kw-alerte\">sévère</span>.</li>\n        <li><span class=\"kw-alerte\">Résistance au traitement</span>.</li>\n        <li><span class=\"kw-etio\">Comorbidité</span> psychiatrique ou non psychiatrique.</li>\n        <li>Situation à risque spécifique (grossesse, post-partum).</li>\n      </ul>","frequence":1},{"id":"66-29","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux généraux de la prise en charge","contenu":"<p><strong>Orientation</strong> — hospitalisation rarement nécessaire, sauf <span class=\"kw-alerte\">risque suicidaire</span>, comorbidité dépressive sévère, ou manifestations anxieuses aiguës très envahissantes.</p>\n      <p><strong>Traitement non pharmacologique</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Éducation thérapeutique</span> : règles hygiéno-diététiques — arrêt des excitants (<span class=\"kw-ci\">tabac</span>, <span class=\"kw-ci\">café</span>, <span class=\"kw-etio\">alcool</span>), alimentation, sommeil, activité physique, relaxation ; information sur les risques des anxiolytiques.</li>\n        <li><span class=\"kw-ttt\">Psychothérapie</span> : les <span class=\"kw-ttt\">TCC</span> sont privilégiées (gestion des émotions et des inquiétudes, techniques de relaxation).</li>\n      </ul>\n      <p><strong>Traitement pharmacologique</strong></p>\n      <ul>\n        <li>Ponctuel : <span class=\"kw-ttt\">BZD</span> (alternative : <span class=\"kw-ttt\">hydroxyzine</span>) si manifestations anxieuses intenses et invalidantes.</li>\n        <li>De fond : <span class=\"kw-ttt\">ISRS</span> ou <span class=\"kw-ttt\">IRSNA</span> dans les formes sévères et invalidantes (BZD possible transitoirement en attendant l’efficacité des <span class=\"kw-ttt\">ISRS</span>).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La PEC du trouble panique est <strong>identique à celle du TAG</strong>, sauf la modalité de psychothérapie : exposition et désensibilisation aux <span class=\"kw-clinique\">sensations physiques des AP</span> et aux situations redoutées en cas d’agoraphobie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes</em></p>","frequence":6},{"id":"66-30","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge de l’attaque de panique","contenu":"<p>L’<span class=\"kw-def\">attaque de panique</span> est la manifestation centrale du trouble panique : crises spontanées et imprévisibles, devenant secondairement liées à une <span class=\"kw-clinique\">anxiété anticipatoire</span> et à la confrontation aux situations redoutées (agoraphobie). Elle dure en moyenne <span class=\"kw-chiffre\">20 à 30 minutes</span> et est <strong>spontanément résolutive</strong>.</p>\n      <p><strong>Prise en charge en urgence (aiguë)</strong> — repose en priorité sur des mesures <span class=\"kw-ttt\">non pharmacologiques</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Mise en condition</span> : installation au calme, suppression des éléments anxiogènes, attitude empathique.</li>\n        <li><span class=\"kw-ttt\">Réassurance</span> : délivrer un <strong>diagnostic positif</strong> (« il s’agit d’une attaque de panique »), informer sur l’<strong>absence de danger de mort</strong> et le caractère <strong>spontanément résolutif</strong> de la crise.</li>\n        <li><span class=\"kw-ttt\">Contrôle ventilatoire</span> : allongement du temps d’expiration (au mieux à lèvres pincées) — stimule le tonus vagal, focalise l’attention et limite l’<span class=\"kw-clinique\">hyperventilation</span>.</li>\n        <li>Éliminer impérativement une <strong>urgence non psychiatrique</strong>, une intoxication ou un sevrage, et écarter le <span class=\"kw-etio\">facteur déclenchant</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Traitement pharmacologique ponctuel.</strong> Si l’AP se prolonge (crise sévère) : <span class=\"kw-ttt\">benzodiazépine</span> par <strong>voie orale</strong> (la voie parentérale n’apporte aucun avantage). Traitement <strong>ponctuel</strong> uniquement, <span class=\"kw-ci\">jamais au long cours</span> (risque de dépendance).</div>\n      <p><strong>À distance / dans le cadre du trouble panique</strong> — <span class=\"kw-ttt\">psychothérapie</span> (TCC : exposition aux sensations physiques des AP) et, dans les formes sévères, traitement de fond par <span class=\"kw-ttt\">ISRS</span> à <strong>doses faibles initialement</strong> ; pour l’AP isolée : information et éducation thérapeutique (reconnaître une récidive, règles hygiéno-diététiques).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 352 — Crise d'angoisse aiguë et attaque de panique</em></p>","frequence":1},{"id":"66-31","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements non pharmacologiques","contenu":"<p>Les <span class=\"kw-ttt\">thérapies cognitivo-comportementales</span> (TCC) sont le traitement non pharmacologique de référence des troubles anxieux.</p>\n      <ul>\n        <li><strong>TAG</strong> : stratégies centrées sur la gestion des émotions et des inquiétudes ; apprentissage de techniques de <span class=\"kw-ttt\">relaxation</span>.</li>\n        <li><strong>Trouble panique</strong> : <span class=\"kw-ttt\">exposition et désensibilisation</span> aux sensations physiques des AP et aux situations redoutées en cas d’agoraphobie.</li>\n        <li><strong>Phobies</strong> : <span class=\"kw-ttt\">restructuration cognitive</span> + <span class=\"kw-ttt\">exposition in vivo graduée</span> / désensibilisation systématique. Les TCC <strong>de groupe</strong> sont les plus efficaces dans la phobie sociale.</li>\n        <li><strong>Refus scolaire anxieux</strong> : approche multidisciplinaire et collaborative — parents, établissement scolaire, professionnels de santé.</li>\n      </ul>","frequence":2},{"id":"66-32","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques au long cours chez l’adulte","contenu":"<p><strong>Traitement de fond</strong> — indiqué dans les formes sévères et invalidantes ou en cas d’insuffisance du traitement non pharmacologique :</p>\n      <ul>\n        <li>Molécules : <span class=\"kw-ttt\">ISRS</span>, voire <span class=\"kw-ttt\">IRSNA</span> (BZD possible transitoirement en attendant leur efficacité).</li>\n        <li>Délai d’action : <span class=\"kw-chiffre\">3 à 4 semaines</span> ; durée du traitement : <span class=\"kw-chiffre\">6 à 12 mois</span>.</li>\n      </ul>\n      <p>Pour les phobies : aucun traitement médicamenteux n’est efficace contre les <strong>phobies spécifiques</strong> ; les <span class=\"kw-ttt\">ISRS</span> / <span class=\"kw-ttt\">IRSNA</span> peuvent être indiqués dans la phobie sociale sévère.</p>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Dans le trouble panique, débuter les <span class=\"kw-ttt\">ISRS</span> à <strong>doses faibles</strong> : les <span class=\"kw-ci\">fortes doses initiales peuvent aggraver les attaques de panique</span>.</div>","frequence":2},{"id":"66-33","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques chez l’enfant et l’adolescent","contenu":"<p>Chez l’enfant et l’adolescent, la <span class=\"kw-ttt\">TCC</span> est recommandée en <strong>première intention</strong> si l’intensité du trouble est légère à modérée. Le traitement pharmacologique de fond est réservé aux formes <strong>sévères et invalidantes</strong> ou en cas d’échec / d’inapplicabilité de la prise en charge non pharmacologique.</p>\n      <ul>\n        <li>Traitement de fond : <span class=\"kw-ttt\">ISRS</span> en <strong>1<sup>re</sup> intention</strong> (chez l’enfant et l’adolescent comme chez l’adulte).</li>\n        <li>Refus scolaire anxieux : <span class=\"kw-ttt\">ISRS</span> ciblant l’<span class=\"kw-etio\">étiologie psychiatrique sous-jacente</span>, indiqué si situation sévère ou ne répondant pas à la prise en charge non pharmacologique.</li>\n        <li>Les <span class=\"kw-ttt\">anxiolytiques / BZD</span> ne sont utilisés que <strong>ponctuellement</strong> et brièvement (manifestations anxieuses intenses) : ils ne modifient pas le trouble au long cours et exposent à un <span class=\"kw-ci\">risque de dépendance</span>.</li>\n      </ul>","frequence":1},{"id":"66-34","rang":"A","rubrique":"Définition","titre":"Connaître la définition des obsessions, des compulsions, des troubles obsessionnels compulsifs","contenu":"<p>Le <strong><span class=\"kw-def\">trouble obsessionnel compulsif</span></strong> (TOC) associe deux types de symptômes : des <span class=\"kw-clinique\">obsessions</span> et/ou des <span class=\"kw-clinique\">compulsions</span>.</p>\n      <table >\n        <thead><tr><th>Symptôme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Obsession</span></td><td>Irruption <strong>intrusive</strong> de pensées, pulsions ou images, en désaccord avec la pensée consciente (<span class=\"kw-def\">égo-dystoniques</span>, jugées inappropriées), <strong>récurrentes et persistantes</strong>, génératrices d’anxiété</td></tr>\n          <tr><td><span class=\"kw-def\">Compulsion</span></td><td>Comportements répétitifs (se laver, ordonner, vérifier) ou actes mentaux (compter, répéter) que le sujet se sent forcé d’accomplir en réponse à une obsession ou selon des règles inflexibles ; visent à <strong>neutraliser l’anxiété</strong>, ne sont pas source de plaisir</td></tr>\n          <tr><td><span class=\"kw-def\">Rituel</span></td><td>Compulsion réalisée de manière très précise et stéréotypée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le diagnostic de TOC peut être posé en présence d’obsessions <strong>seules</strong>, de compulsions <strong>seules</strong>, ou des deux.</div>","frequence":2},{"id":"66-35","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence, l’âge de début des troubles","contenu":"<ul>\n        <li>Prévalence : <span class=\"kw-chiffre\">2 %</span> — un des troubles psychiatriques les plus fréquents et les plus invalidants.</li>\n        <li>Sujet jeune : début <span class=\"kw-chiffre\">&lt; 25 ans</span> dans <span class=\"kw-chiffre\">65 %</span> des cas ; début dans l’enfance dans <span class=\"kw-chiffre\">1/3</span> des cas.</li>\n        <li><strong>Sex-ratio à 1</strong> : le TOC est le <strong>seul trouble anxieux qui n’est pas à prédominance féminine</strong>.</li>\n      </ul>","frequence":1},{"id":"66-36","rang":"A","rubrique":"Étiologie","titre":"Savoir que l’étiologie est multifactorielle","contenu":"<p>L’origine du TOC est <strong>multifactorielle</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Vulnérabilité génétique</span> : gènes codant pour des protéines des systèmes <span class=\"kw-bio\">sérotoninergique</span> et <span class=\"kw-bio\">dopaminergique</span>.</li>\n        <li><span class=\"kw-etio\">Facteurs environnementaux</span> : restent extrêmement mal connus.</li>\n      </ul>","frequence":0},{"id":"66-37","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie","contenu":"<p>Le diagnostic est porté sur la présence d’<span class=\"kw-clinique\">obsessions</span> et/ou de <span class=\"kw-clinique\">compulsions</span>, fréquemment associées à des <span class=\"kw-clinique\">conduites d’évitement</span>.</p>\n      <table >\n        <thead><tr><th>Thème</th><th>Obsessions</th><th>Compulsions / rituels</th></tr></thead>\n        <tbody>\n          <tr><td>Contamination</td><td>Obsessions de contamination</td><td>Lavage ; évitement du contact</td></tr>\n          <tr><td>Erreur</td><td>Ordre, symétrie, exactitude ; pensées magiques associées</td><td>Vérifications ; alignement / symétrie des objets</td></tr>\n          <tr><td>Pensées interdites</td><td>Catastrophe, impulsion agressive, thématique sexuelle, religieuse ou somatique</td><td>Vérifications ; prières / rituels ; rituels mentaux</td></tr>\n          <tr><td>Accumulation</td><td>Peur de perdre un objet</td><td>Accumulation compulsive (<span class=\"kw-clinique\">syllogomanie</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Insight</strong> (conscience du trouble) : variable ; la majorité des patients ont un bon insight, mais <span class=\"kw-chiffre\">5 à 25 %</span> ont un <span class=\"kw-alerte\">insight faible</span> — facteur pronostique de l’évolution à long terme.</p>\n      <div class=\"callout callout-info\"><strong>Distinction-clé.</strong> <span class=\"kw-def\">Impulsion</span> = acte insuffisamment réfléchi, sans prise en compte des conséquences (trouble des conduites, personnalité antisociale). <span class=\"kw-def\">Compulsion</span> = action longuement réfléchie qui diminue l’anxiété liée à une obsession.</div>","frequence":2},{"id":"66-38","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités chez l’enfant et l’adolescent","contenu":"<p>Les présentations cliniques du TOC chez l’enfant sont globalement <strong>similaires à celles de l’adulte</strong>. Particularités :</p>\n      <ul>\n        <li>Certains rituels développementaux n’ont <strong>aucune valeur pathologique</strong> (ex. rituels d’endormissement) — à ne pas confondre avec un TOC.</li>\n        <li>Obsessions / compulsions souvent <span class=\"kw-clinique\">multiples</span> et de contenu fluctuant.</li>\n        <li>Entourage familial souvent impliqué dans les compulsions.</li>\n        <li><span class=\"kw-alerte\">Faible insight</span> fréquent.</li>\n        <li>L’interruption des compulsions peut se manifester par des troubles du comportement : crises de <span class=\"kw-clinique\">colère</span>, <span class=\"kw-clinique\">agressivité</span>, <span class=\"kw-clinique\">irritabilité</span>.</li>\n      </ul>","frequence":1},{"id":"66-39","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités chez la personne âgée","contenu":"<p>Il n’existe <strong>pas de spécificité sémiologique</strong> du TOC chez le sujet âgé.</p>","frequence":0},{"id":"66-40","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques DSM-5","contenu":"<table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td>Présence d’<span class=\"kw-clinique\">obsessions</span>, de <span class=\"kw-clinique\">compulsions</span>, ou des deux</td></tr>\n          <tr><td>B</td><td>Perte de temps considérable (ex. <span class=\"kw-chiffre\">&gt; 1 h/jour</span>) <strong>ou</strong> détresse cliniquement significative <strong>ou</strong> altération du fonctionnement</td></tr>\n          <tr><td>C</td><td>Symptômes non imputables à une <span class=\"kw-etio\">substance</span> ni à une autre affection médicale</td></tr>\n          <tr><td>D</td><td>Perturbation non mieux expliquée par un autre trouble mental</td></tr>\n        </tbody>\n      </table>\n      <p>Spécifier la <strong>prise de conscience du trouble</strong> (insight) : bonne / assez bonne, mauvaise, ou absente.</p>","frequence":1},{"id":"66-41","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<table >\n        <thead><tr><th>Catégorie</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td>Non psychiatriques</td><td><strong>Mouvements anormaux :</strong> <span class=\"kw-clinique\">tics</span> (non précédés d’obsessions)<br><strong>Noyaux gris centraux :</strong> <span class=\"kw-etio\">syndrome de Gilles de la Tourette</span>, <span class=\"kw-etio\">chorée de Huntington</span></td></tr>\n          <tr><td>Psychiatriques</td><td><strong><span class=\"kw-etio\">Schizophrénie</span></strong> (principal DD : idée délirante = conviction inébranlable ≠ reconnaissance du caractère irrationnel dans l’obsession)<br><strong>EDC :</strong> ruminations anxieuses congruentes à l’humeur<br><strong>Troubles anxieux :</strong> TAG, phobie (situations réelles, ≠ irrationnel du TOC)<br><strong>Personnalité obsessionnelle-compulsive :</strong> pas d’obsession ni de compulsion</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique</em></p>","frequence":2},{"id":"66-42","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux généraux de la prise en charge","contenu":"<p><strong>Traitement non pharmacologique</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Éducation thérapeutique</span> : place primordiale (trouble chronique, vécu comme honteux → retard diagnostique). Rassurer, nommer le trouble, expliquer les traitements.</li>\n        <li>Impliquer l’entourage : <strong>ne pas participer aux rituels</strong>, ne pas faciliter l’évitement, ne pas répondre aux demandes de réassurance répétées.</li>\n        <li><span class=\"kw-ttt\">TCC</span> : <span class=\"kw-ttt\">exposition avec prévention de la réponse</span> = méthode de référence (≈ <span class=\"kw-chiffre\">50 %</span> de répondeurs).</li>\n      </ul>\n      <p><strong>Traitement pharmacologique</strong></p>\n      <ul>\n        <li>Ponctuel : <span class=\"kw-ttt\">anxiolytiques</span> — palliatifs de l’anxiété, ils <span class=\"kw-ci\">ne réduisent ni les obsessions ni les rituels</span>.</li>\n        <li>De fond : <span class=\"kw-ttt\">ISRS</span> à <strong>posologies élevées</strong> (souvent le double de la posologie de l’EDC), délai d’efficacité <span class=\"kw-chiffre\">6 à 12 semaines</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L’association <span class=\"kw-ttt\">TCC + ISRS</span> est plus efficace que chacune des approches séparément.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes</em></p>","frequence":1},{"id":"66-43","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires et leurs indications","contenu":"<p>Le diagnostic de TOC est <strong>clinique</strong> ; il n’existe pas d’examen complémentaire de routine. Le critère DSM-5 impose seulement d’écarter une <span class=\"kw-etio\">substance</span> et une <span class=\"kw-etio\">affection médicale</span> à l’origine des symptômes.</p>\n      <p>Un avis neurologique et une <span class=\"kw-imagerie\">imagerie cérébrale</span> ne se justifient que devant une <strong>présentation atypique</strong> faisant suspecter une pathologie neurologique des <span class=\"kw-etio\">noyaux gris centraux</span> — qui peut provoquer des symptômes obsessionnels et compulsifs :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Syndrome de Gilles de la Tourette</span> ;</li>\n        <li><span class=\"kw-etio\">Chorée de Huntington</span>.</li>\n      </ul>","frequence":1},{"id":"66-44","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements non pharmacologiques","contenu":"<p>Les <span class=\"kw-ttt\">thérapies cognitivo-comportementales</span> ont fait la preuve de leur efficacité dans le TOC (≈ <span class=\"kw-chiffre\">50 %</span> de répondeurs).</p>\n      <p><strong>Exposition avec prévention de la réponse</strong> (méthode de référence) :</p>\n      <ul>\n        <li>Exposition progressive, in vivo et en imagination, aux conditions anxiogènes déclenchant les obsessions.</li>\n        <li>Empêcher toute compulsion / rituel (observable ou mental).</li>\n        <li>Apprendre au patient à faire face à l’anxiété et à développer son sentiment d’efficacité personnelle.</li>\n      </ul>","frequence":1},{"id":"66-45","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques au long cours chez l’adulte","contenu":"<ul>\n        <li>Indication : TOC de l’adulte.</li>\n        <li>Molécule : <span class=\"kw-ttt\">ISRS</span> (efficacité démontrée chez l’adulte comme chez l’enfant / adolescent).</li>\n        <li>Posologies : <strong>élevées</strong>, souvent le double de la posologie recommandée dans l’EDC.</li>\n        <li>Délai d’efficacité : plus long que dans la <span class=\"kw-def\">dépression</span> — <span class=\"kw-chiffre\">6 à 12 semaines</span>.</li>\n      </ul>","frequence":1},{"id":"66-46","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques chez l’enfant et l’adolescent","contenu":"<p>Chez l’enfant et l’adolescent, le traitement de fond par <span class=\"kw-ttt\">ISRS</span> est indiqué en cas d’<strong>échec du traitement non pharmacologique seul</strong> (TCC avec exposition et prévention de la réponse).</p>","frequence":0},{"id":"66-47","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un événement potentiellement traumatique, d’un trouble stress aigu, d’un trouble stress post-traumatique, des symptômes dissociatifs","contenu":"<table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Événement traumatique</span> (ET)</td><td>Être menacé de mort, trouver la mort, subir des blessures graves ou des violences sexuelles. Modes d’exposition : victime directe ; témoin direct ; apprendre qu’un ET est arrivé à un proche ; exposition répétée dans un cadre professionnel (<span class=\"kw-clinique\">pompiers</span>, soignants, policiers)</td></tr>\n          <tr><td><span class=\"kw-def\">Trouble stress aigu</span> (TSA)</td><td>Symptomatologie similaire au TSPT, débutant dans les jours suivant le traumatisme, durant <span class=\"kw-chiffre\">≤ 1 mois</span></td></tr>\n          <tr><td><span class=\"kw-def\">Trouble stress post-traumatique</span> (TSPT)</td><td>Survenue de symptômes caractéristiques à la suite de l’exposition à un ET, persistant <span class=\"kw-chiffre\">&gt; 1 mois</span></td></tr>\n          <tr><td><span class=\"kw-def\">Symptômes dissociatifs</span></td><td>Altération de la perception de la réalité, de l’environnement ou de soi-même ; <span class=\"kw-clinique\">dépersonnalisation</span>, <span class=\"kw-clinique\">déréalisation</span>, amnésie de l’événement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Distracteur EDN.</strong> L’exposition répétée à un événement traumatique <strong>via un média</strong> n’est <span class=\"kw-alerte\">pas</span> un événement traumatique au sens du TSPT.</div>","frequence":1},{"id":"66-48","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<ul>\n        <li>Prévalence du TSPT sur la vie entière : <span class=\"kw-chiffre\">5 à 10 %</span> de la population générale.</li>\n        <li>Risque de TSPT après exposition à un traumatisme : environ <span class=\"kw-chiffre\">10 %</span>, pouvant aller jusqu’à <span class=\"kw-chiffre\">50 %</span> selon l’événement (viol, combats, détention, génocide).</li>\n        <li>Chez l’enfant / l’adolescent : exposition à un ET fréquente (≈ <span class=\"kw-chiffre\">1/4</span>) ; environ <span class=\"kw-chiffre\">1/10</span> développe un TSPT avant <span class=\"kw-chiffre\">18 ans</span>.</li>\n      </ul>","frequence":0},{"id":"66-49","rang":"B","rubrique":"Étiologie","titre":"Savoir que l’étiologie est multifactorielle","contenu":"<p>L’étiologie du TSPT est <strong>multifactorielle</strong>. Principaux <span class=\"kw-etio\">facteurs de risque</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Facteurs génétiques</span> ; sexe <strong>féminin</strong> (prédominance <span class=\"kw-chiffre\">2F/1H</span>).</li>\n        <li><span class=\"kw-etio\">Antécédents psychiatriques</span> ; antécédents d’autres événements traumatiques.</li>\n        <li>Populations plus exposées (personnes ayant émigré de zones instables ou en guerre).</li>\n        <li>Caractéristiques de l’ET (type, sévérité, durée, proximité de l’exposition).</li>\n        <li>Faible qualité du <span class=\"kw-etio\">soutien social</span> ; niveau socio-économique bas.</li>\n      </ul>","frequence":0},{"id":"66-50","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie","contenu":"<p>Le <span class=\"kw-def\">TSPT</span> associe quatre grandes familles de symptômes après l’exposition à un ET.</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td>Syndrome de répétition</td><td><span class=\"kw-clinique\">Reviviscences</span> involontaires, vivaces, envahissantes ; <span class=\"kw-clinique\">cauchemars traumatiques</span> ; <span class=\"kw-clinique\">réactions dissociatives</span> (flash-backs, durée secondes-minutes) ; détresse psychique lors de l’exposition à des indices évoquant l’ET</td></tr>\n          <tr><td>Syndrome d’évitement</td><td><span class=\"kw-clinique\">Évitement</span> des rappels <strong>externes</strong> (personnes, lieux, situations) et des rappels <strong>internes</strong> (souvenirs, pensées, sentiments)</td></tr>\n          <tr><td>Hyperactivation neurovégétative</td><td><span class=\"kw-clinique\">Altérations du sommeil</span> souvent au 1ᵉʳ plan ; <span class=\"kw-clinique\">irritabilité</span> / accès de colère ; <span class=\"kw-clinique\">hypervigilance</span> avec réactions de sursaut exagérées ; troubles de la concentration et de la mémoire</td></tr>\n          <tr><td>Altérations négatives des cognitions et de l’humeur</td><td><span class=\"kw-clinique\">Distorsions cognitives</span> persistantes (sur soi-même et sur autrui) ; incapacité d’éprouver des émotions positives ; sentiment de détachement ; diminution des intérêts</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Distracteur EDN (tombé en annale).</strong> Le <span class=\"kw-alerte\">déni de l’événement traumatique n’est PAS évocateur de TSPT</span>.</div>","frequence":9},{"id":"66-51","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités chez l’enfant et l’adolescent","contenu":"<ul>\n        <li>Les syndromes de répétition et d’évitement sont <strong>difficiles à identifier</strong> chez l’enfant (moindres capacités d’expression verbale et d’abstraction).</li>\n        <li>Le syndrome de répétition se manifeste souvent par la <span class=\"kw-clinique\">répétition de certains aspects de l’ET dans les jeux, les dessins et les cauchemars</span>.</li>\n        <li>Chez l’adolescent, des <span class=\"kw-clinique\">comportements agressifs et impulsifs</span> peuvent être au 1ᵉʳ plan.</li>\n      </ul>","frequence":1},{"id":"66-52","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques DSM-5 des troubles stress aigu et stress post-traumatique","contenu":"<p><strong>TSPT</strong></p>\n      <table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td>Exposition à la mort, à une menace de mort, à une blessure grave ou à des violences sexuelles (victime, témoin, proche, exposition répétée professionnelle)</td></tr>\n          <tr><td>B</td><td><span class=\"kw-chiffre\">≥ 1</span> symptôme envahissant (souvenirs, rêves, réactions dissociatives, détresse, réactions physiologiques)</td></tr>\n          <tr><td>C</td><td><span class=\"kw-clinique\">Évitement</span> persistant des stimuli associés à l’ET</td></tr>\n          <tr><td>D</td><td><span class=\"kw-chiffre\">≥ 2</span> altérations négatives des cognitions et de l’humeur</td></tr>\n          <tr><td>E</td><td><span class=\"kw-chiffre\">≥ 2</span> altérations de l’éveil et de la réactivité</td></tr>\n          <tr><td>F</td><td>Perturbation durant <span class=\"kw-chiffre\">&gt; 1 mois</span></td></tr>\n          <tr><td>G-H</td><td>Souffrance / altération du fonctionnement ; non imputable à une substance ou affection médicale</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trouble stress aigu</strong> — principal DD du TSPT : <span class=\"kw-chiffre\">≥ 9/14</span> symptômes, débutant après l’ET, durée <span class=\"kw-chiffre\">3 jours à 1 mois</span>.</p>\n      <div class=\"callout callout-info\"><strong>Discriminant.</strong> Durée : <span class=\"kw-def\">TSA</span> = <span class=\"kw-chiffre\">≤ 1 mois</span> (typiquement <span class=\"kw-chiffre\">3 jours</span>-1 mois) ; <span class=\"kw-def\">TSPT</span> = <span class=\"kw-chiffre\">&gt; 1 mois</span>.</div>","frequence":3},{"id":"66-53","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principaux généraux de la prise en charge immédiate au décours d’un événement potentiellement traumatique","contenu":"<table >\n        <thead><tr><th>Axe</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Objectifs</td><td>Repérer / traiter les manifestations aiguës de stress (notamment <span class=\"kw-clinique\">symptomatologie dissociative</span>) ; mettre à disposition une aide psychologique ; informer les victimes et leurs proches</td></tr>\n          <tr><td>Médical</td><td>Techniques de <span class=\"kw-ttt\">defusing</span> (« déchocage psychologique ») : réduire la charge émotionnelle, identifier les personnes vulnérables — <strong>sans</strong> demander à la personne de raconter l’événement</td></tr>\n          <tr><td>Juridique</td><td><strong>Certificat médical initial</strong> systématique ; prélèvements à proposer en cas d’agression sexuelle</td></tr>\n          <tr><td>Social</td><td>Orientation vers des associations spécialisées ou des groupes d’entraide</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pièges.</strong> Les <span class=\"kw-ci\">benzodiazépines</span> sont <span class=\"kw-ci\">à éviter</span> dans les suites d’une exposition traumatique. Les interventions précoces auprès des victimes <strong>ne suffisent pas</strong> <span class=\"kw-ci\">à éviter</span> le développement d’un TSPT ou d’un TSA.</div>","frequence":1},{"id":"66-54","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux généraux de la prise en charge des troubles stress aigu et post-traumatique","contenu":"<ul>\n        <li>La <span class=\"kw-ttt\">psychothérapie</span> est le <strong>traitement de 1ʳᵉ ligne</strong>.</li>\n        <li>Le traitement <span class=\"kw-ttt\">pharmacologique</span> ne constitue <strong>pas</strong> un traitement de 1ʳᵉ intention : réservé aux symptômes sévères ou chroniques, ou aux patients ne pouvant ou ne souhaitant pas suivre une psychothérapie.</li>\n        <li>Recours possible à des groupes de pairs et à des associations apportant une aide sociale et juridique.</li>\n      </ul>","frequence":1},{"id":"66-55","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements non pharmacologiques","contenu":"<table >\n        <thead><tr><th>Technique</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">TCC</span></td><td>Gestion de l’anxiété, lutte contre les évitements ; relaxation, exposition graduée, restructuration cognitive — d’autant plus efficaces si débutées précocement</td></tr>\n          <tr><td><span class=\"kw-ttt\">Thérapie d’exposition prolongée</span> (<span class=\"kw-imagerie\">TEP</span>)</td><td>Désensibilisation vis-à-vis de l’événement (imaginaire ou réelle, progressive, répétée, contrôlée) → phénomène d’<strong><span class=\"kw-def\">habituation</span></strong></td></tr>\n          <tr><td><span class=\"kw-ttt\">EMDR</span></td><td>Retraitement des souvenirs traumatiques par stimulation bilatérale, pour qu’ils acquièrent le statut de souvenirs débarrassés des émotions négatives</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"66-56","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques au long cours chez l’adulte","contenu":"<p>Le traitement pharmacologique n’est <strong>pas</strong> un traitement de 1ʳᵉ intention. Indications : symptômes <span class=\"kw-alerte\">sévères</span> ou <span class=\"kw-alerte\">chroniques</span> ; patients ne pouvant ou ne souhaitant pas suivre une psychothérapie.</p>\n      <ul>\n        <li>Molécule : <span class=\"kw-ttt\">ISRS</span>.</li>\n        <li>Si un anxiolytique est nécessaire : <span class=\"kw-ttt\">antipsychotiques sédatifs</span> ou <span class=\"kw-ttt\">hydroxyzine</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> L’usage des <span class=\"kw-ci\">benzodiazépines</span> est <span class=\"kw-ci\">à éviter</span> dans les suites d’une exposition traumatique.</div>","frequence":1},{"id":"66-57","rang":"A","rubrique":"Définition","titre":"Connaître la définition du stress et de l’adaptation au stress, des troubles de l’adaptation","contenu":"<p>Le <strong><span class=\"kw-def\">trouble de l’adaptation</span></strong> correspond à la présence de symptômes <span class=\"kw-clinique\">réactionnels</span> à un ou plusieurs événements de vie auxquels le sujet n’arrive pas à s’adapter.</p>\n      <ul>\n        <li>Survient quand les <strong>capacités d’adaptation</strong> du patient à son milieu sont momentanément <strong>dépassées</strong>.</li>\n        <li>La réaction est jugée <strong>excessive</strong> par rapport à la réaction habituelle à un facteur de stress similaire.</li>\n        <li>Les symptômes <strong>ne remplissent pas</strong> les critères diagnostiques d’un trouble de l’humeur ou d’un autre trouble anxieux.</li>\n      </ul>\n      <p><strong>Physiopathologie</strong> : après un événement stressant, la réaction initiale est le <span class=\"kw-clinique\">choc</span> (coexistence d’un <span class=\"kw-clinique\">déni</span> et d’une <span class=\"kw-clinique\">sidération</span>) ; les capacités d’adaptation se mettent ensuite en place (dépendant de facteurs génétiques et environnementaux).</p>","frequence":1},{"id":"66-58","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<p>Prévalence du trouble de l’adaptation : environ <span class=\"kw-chiffre\">10 %</span>.</p>\n      <p>C’est l’un des motifs de consultation les plus <strong>fréquents</strong> : <span class=\"kw-chiffre\">10 à 20 %</span> en médecine générale et <span class=\"kw-chiffre\">5 à 20 %</span> en psychiatrie ambulatoire.</p>","frequence":0},{"id":"66-59","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution","contenu":"<p><strong>Facteurs de risque</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Trouble de la personnalité</span> = principal facteur de risque (vulnérabilité psychiatrique limitant les capacités d’adaptation).</li>\n        <li>Conditions d’existence difficiles : <span class=\"kw-etio\">pauvreté</span>, <span class=\"kw-etio\">isolement social</span>, <span class=\"kw-etio\">contexte migratoire</span>.</li>\n      </ul>\n      <p><strong>Évolution et pronostic</strong></p>\n      <ul>\n        <li>Trouble <strong>transitoire</strong> par définition : cède dans les <span class=\"kw-chiffre\">&lt; 6 mois</span> suivant la fin du facteur de stress.</li>\n        <li>Pronostic globalement favorable : pas de complication ni de séquelle chez <span class=\"kw-chiffre\">75 %</span> des adultes.</li>\n        <li>Évolution possible vers des <span class=\"kw-alerte\">complications</span> : EDC, troubles anxieux, troubles liés à l’usage de substance, <span class=\"kw-alerte\">suicide</span> (<span class=\"kw-chiffre\">2 à 4 %</span> de tentatives, jusqu’à <span class=\"kw-chiffre\">10 %</span> chez l’adolescent).</li>\n      </ul>","frequence":1},{"id":"66-60","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie","contenu":"<p><strong>Événements stressants déclencheurs</strong> — changement imposant une adaptation, dans le domaine professionnel et/ou personnel : annonce diagnostique d’une pathologie grave, transitions de vie (mariage, rupture, changement de métier, difficultés financières). Des événements d’apparence non stressante peuvent suffire chez les personnes vulnérables.</p>\n      <p><strong>Manifestations</strong></p>\n      <ul>\n        <li>Symptômes <span class=\"kw-clinique\">émotionnels</span> ou <span class=\"kw-clinique\">comportementaux</span> ne remplissant pas les critères d’un autre trouble psychiatrique.</li>\n        <li>Caractère pathologique = <span class=\"kw-clinique\">altération du fonctionnement socio-professionnel</span>.</li>\n        <li>Délai d’apparition : au plus tard dans les <span class=\"kw-chiffre\">&lt; 3 mois</span> suivant le début du facteur de stress.</li>\n        <li>Durée : disparition <span class=\"kw-chiffre\">&lt; 6 mois</span> après l’arrêt du facteur de stress.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Les troubles liés au deuil <span class=\"kw-alerte\">ne font pas partie</span> des troubles de l’adaptation : ils sont regroupés dans les <strong>deuils pathologiques</strong>.</div>","frequence":1},{"id":"66-61","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques chez l’enfant et l’adolescent","contenu":"<p>Chez l’enfant et l’adolescent, les contextes d’apparition typiques du trouble de l’adaptation sont : la <span class=\"kw-clinique\">séparation des parents</span>, l’<span class=\"kw-clinique\">entrée au collège ou au lycée</span>, ou l’<span class=\"kw-clinique\">échec à un examen</span>.</p>","frequence":0},{"id":"66-62","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les spécificités sémiologiques chez la personne âgée","contenu":"<p>Il n’existe <strong>pas de spécificité sémiologique</strong> du trouble de l’adaptation chez la personne âgée.</p>","frequence":0},{"id":"66-63","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères DSM-5 du trouble de l’adaptation","contenu":"<table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td>Symptômes émotionnels ou comportementaux en réponse à un / des facteur(s) de stress identifiable(s), au cours des <span class=\"kw-chiffre\">&lt; 3 mois</span> suivant l’exposition</td></tr>\n          <tr><td>B</td><td>Symptômes cliniquement significatifs : <span class=\"kw-clinique\">détresse marquée</span> hors de proportion <strong>ou</strong> altération significative du fonctionnement</td></tr>\n          <tr><td>C</td><td>Ne répond pas aux critères d’un autre trouble mental et n’est pas une exacerbation d’un trouble préexistant</td></tr>\n          <tr><td>D</td><td>Symptômes ≠ ceux d’un <strong>deuil normal</strong></td></tr>\n          <tr><td>E</td><td>Les symptômes ne persistent pas au-delà de <span class=\"kw-chiffre\">6 mois</span> après la fin du facteur de stress</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"66-64","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<table >\n        <thead><tr><th>Catégorie</th><th>Diagnostic différentiel</th></tr></thead>\n        <tbody>\n          <tr><td>Réaction adaptée au stress</td><td>Le trouble de l’adaptation s’en distingue par l’<strong>intensité des symptômes</strong> et/ou l’altération du fonctionnement</td></tr>\n          <tr><td>Non psychiatriques</td><td>Comme devant tout tableau psychiatrique, une cause médicale non psychiatrique doit être recherchée</td></tr>\n          <tr><td>Psychiatriques</td><td><span class=\"kw-def\">TSA</span> et <span class=\"kw-def\">TSPT</span> : le trouble de l’adaptation s’en distingue par l’<strong>absence de syndrome de répétition et d’évitement</strong> ; <span class=\"kw-def\">EDC</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"66-65","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications du recours au psychiatre","contenu":"<p>Le <strong>recours au psychiatre</strong> devant un trouble de l’adaptation est indiqué si :</p>\n      <ul>\n        <li>Trouble <span class=\"kw-alerte\">sévère</span>.</li>\n        <li><span class=\"kw-alerte\">Résistance au traitement</span>.</li>\n        <li><span class=\"kw-etio\">Comorbidité</span> psychiatrique ou non psychiatrique.</li>\n        <li>Situation à risque spécifique (grossesse, post-partum).</li>\n      </ul>","frequence":0},{"id":"66-66","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications d’hospitalisation en psychiatrie","contenu":"<p>L’hospitalisation en psychiatrie devant un trouble de l’adaptation doit rester <strong>exceptionnelle</strong>. Indications :</p>\n      <ul>\n        <li>Prise en charge d’une <span class=\"kw-alerte\">crise suicidaire</span> — l’évaluation du risque suicidaire est systématique.</li>\n        <li><span class=\"kw-etio\">Environnement très négatif</span>, aggravant ou causant le trouble (mise à distance, évaluation et intervention sur cet environnement).</li>\n      </ul>","frequence":0},{"id":"66-67","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques","contenu":"<p>Le recours aux psychotropes dans le trouble de l’adaptation est parfois nécessaire, à visée <strong>symptomatique</strong> :</p>\n      <ul>\n        <li>Symptômes anxieux invalidants : <span class=\"kw-ttt\">BZD</span> (alternative : <span class=\"kw-ttt\">hydroxyzine</span>).</li>\n        <li>Perturbations importantes du sommeil chez l’adulte : <span class=\"kw-ttt\">zolpidem</span> ou <span class=\"kw-ttt\">zopiclone</span>.</li>\n      </ul>","frequence":0},{"id":"66-68","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements pharmacologiques chez l’enfant et l’adolescent","contenu":"<p>Chez l’enfant et l’adolescent, le traitement <span class=\"kw-ttt\">psychothérapeutique</span> est à <strong>privilégier en première intention</strong> (verbalisation autour de la situation stressante). Le trouble de l’adaptation étant le plus souvent <strong>spontanément résolutif</strong>, il n’existe <strong>pas de traitement pharmacologique de référence</strong>.</p>\n      <ul>\n        <li>Les <span class=\"kw-ttt\">psychotropes</span> ne sont indiqués qu’à visée <strong>symptomatique</strong> (anxiété, troubles du sommeil invalidants) et en <strong>2<sup>e</sup> intention</strong>.</li>\n        <li>Toujours évaluer le <span class=\"kw-alerte\">risque suicidaire</span>, particulièrement élevé à l’adolescence.</li>\n      </ul>","frequence":0},{"id":"66-69","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des traitements non pharmacologiques","contenu":"<p>Le traitement <span class=\"kw-ttt\">psychothérapeutique</span> est à <strong>privilégier</strong> dans le trouble de l’adaptation.</p>\n      <ul>\n        <li>Objectif : permettre une <strong>verbalisation</strong> autour de la situation stressante et de ses conséquences sur la vie du sujet.</li>\n        <li>Différents types de psychothérapie peuvent être indiqués.</li>\n      </ul>","frequence":0},{"id":"66-70","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la personnalité, des rroubles de la personnalité (critères diagnostiques généraux DSM-5)","contenu":"<p>La <strong><span class=\"kw-def\">personnalité</span></strong> désigne ce qu’il y a de stable et d’unique dans le fonctionnement psychologique d’un individu. Elle associe le <span class=\"kw-def\">tempérament</span> (aspects biologiques, innés, stables) et le <span class=\"kw-def\">caractère</span> (déterminé par les expériences de vie et l’apprentissage social, susceptible de varier). La personnalité normale est <strong>souple et adaptable</strong>.</p>\n      <p>Le <strong><span class=\"kw-def\">trouble de la personnalité</span></strong> correspond à des traits de personnalité particulièrement marqués et <strong>rigides</strong>, associés à une <span class=\"kw-clinique\">altération du fonctionnement social</span> et à une <span class=\"kw-clinique\">incapacité à s’adapter</span> aux différentes situations de la vie.</p>\n      <p><strong>Critères diagnostiques généraux DSM-5</strong></p>\n      <table >\n        <thead><tr><th>Critère</th><th>Énoncé</th></tr></thead>\n        <tbody>\n          <tr><td>A</td><td>Modalité durable de l’expérience vécue et des conduites déviant notablement de la culture de l’individu, dans <span class=\"kw-chiffre\">≥ 2</span> domaines : cognition, affectivité, fonctionnement interpersonnel, contrôle des impulsions</td></tr>\n          <tr><td>B</td><td>Modalités <strong>rigides</strong> envahissant des situations personnelles et sociales très diverses</td></tr>\n          <tr><td>C</td><td>Souffrance cliniquement significative ou altération du fonctionnement</td></tr>\n          <tr><td>D</td><td>Mode d’évolution <strong>stable et prolongé</strong> ; 1ʳᵉˢ manifestations décelables au plus tard à l’adolescence ou au début de l’âge adulte</td></tr>\n          <tr><td>E-F</td><td>Non mieux expliqué par un autre trouble mental ; non dû à une substance ou à une pathologie non psychiatrique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Particularité.</strong> L’expression du trouble est intégrée dans la façon d’être du sujet (<span class=\"kw-def\">égo-syntonique</span>) : il n’y a <strong>pas de rupture avec un état antérieur</strong>, contrairement aux autres troubles psychiatriques.</div>","frequence":0},{"id":"66-71","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence","contenu":"<ul>\n        <li>Prévalence des troubles de la personnalité en population générale : <span class=\"kw-chiffre\">10 %</span>.</li>\n        <li>Prévalence de chacun des troubles : <span class=\"kw-chiffre\">1 à 3 %</span>.</li>\n        <li><span class=\"kw-chiffre\">50 %</span> des patients ont <span class=\"kw-chiffre\">≥ 2</span> troubles de la personnalité.</li>\n        <li>Trouble de la personnalité le plus fréquent : <span class=\"kw-etio\">borderline</span>.</li>\n      </ul>","frequence":0},{"id":"66-72","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution","contenu":"<p><strong>Facteurs de risque</strong> — physiopathologie reposant sur l’interaction de <span class=\"kw-etio\">facteurs de vulnérabilité génétiques</span> et de <span class=\"kw-etio\">facteurs environnementaux</span> (<span class=\"kw-etio\">traumatismes infantiles</span>, négligences physiques ou émotionnelles dans l’enfance).</p>\n      <p><strong>Risques</strong></p>\n      <ul>\n        <li>Difficultés relationnelles fréquentes.</li>\n        <li>Risque accru d’<span class=\"kw-alerte\">auto-mutilation</span> et de <span class=\"kw-alerte\">suicide</span> : mortalité par suicide élevée, surtout pour le <strong>cluster B</strong>.</li>\n        <li>Facteur de vulnérabilité à d’autres troubles psychiatriques : dépressifs, anxieux, addictifs.</li>\n      </ul>\n      <p><strong>Évolution</strong> — dépend du type de personnalité et des troubles associés : peut être stable, s’aggraver ou s’améliorer avec l’âge.</p>","frequence":1},{"id":"66-73","rang":"A","rubrique":"Diagnostic","titre":"Connaître la sémiologie","contenu":"<p>Les <span class=\"kw-def\">troubles de la personnalité</span> sont regroupés en <strong>3 clusters</strong> selon leur caractéristique dominante.</p>\n      <p><strong>Cluster A — caractéristique psychotique</strong></p>\n      <table >\n        <thead><tr><th>Trouble</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Paranoïaque</span></td><td>Rigidité ; très peu d’émotions exprimées ; <span class=\"kw-clinique\">méfiance généralisée</span> envers autrui ; altération du jugement. Peut se compliquer d’un trouble délirant persistant</td></tr>\n          <tr><td><span class=\"kw-etio\">Schizoïde</span></td><td>Tendance à l’isolement ; absence d’intérêt pour autrui ; froideur, réactivité émotionnelle peu marquée. Peut précéder une <span class=\"kw-etio\">schizophrénie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Schizotypique</span></td><td>Croyances bizarres, distorsions cognitives ; champs d’intérêt « originaux » ; compétences sociales altérées ; affects pauvres ou inadéquats. Peut précéder une <span class=\"kw-etio\">schizophrénie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cluster B — caractéristique émotionnelle</strong></p>\n      <table >\n        <thead><tr><th>Trouble</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Antisociale</span></td><td><span class=\"kw-clinique\">Impulsivité</span>, passages à l’acte ; transgressions répétées des droits d’autrui ; absence de culpabilité ; manipulation. Biographie marquée par l’instabilité, trouble des conduites avant <span class=\"kw-chiffre\">15 ans</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Borderline</span></td><td>Instabilité de l’identité, instabilité affective (sentiment chronique de vide), instabilité interpersonnelle (idéalisation / rejet, peur de l’abandon) ; impulsivité (<span class=\"kw-alerte\">auto-mutilations</span>, <span class=\"kw-alerte\">TS répétées</span>) ; symptômes psychotiques / dissociatifs transitoires. Risque suicidaire <span class=\"kw-chiffre\">8-10 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Histrionique</span></td><td>Labilité émotionnelle, hyperexpressivité, théâtralisme ; suggestibilité ; quête affective excessive, attitude séductrice. TS fréquentes</td></tr>\n          <tr><td><span class=\"kw-etio\">Narcissique</span></td><td>Sens grandiose de sa propre importance ; tolère mal la critique ; manque d’empathie ; estime de soi en réalité fragile</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cluster C — caractéristique anxieuse</strong></p>\n      <table >\n        <thead><tr><th>Trouble</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Évitante</span></td><td>Inhibition relationnelle, mésestime de soi, hypersensibilité au jugement négatif ; conduites d’évitement social. DD : phobie sociale</td></tr>\n          <tr><td><span class=\"kw-etio\">Dépendante</span></td><td>Besoin excessif d’être pris en charge ; dévalorisation ; n’ose pas s’affirmer ni exprimer un désaccord</td></tr>\n          <tr><td><span class=\"kw-etio\">Obsessionnelle-compulsive</span></td><td>Méticulosité, souci du détail et de l’ordre, rigidité, perfectionnisme ; émotions exprimées avec contrôle. <strong>Pas d’obsession ni de compulsion</strong> (≠ TOC)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 65 — Trouble délirant persistant</em></p>","frequence":6},{"id":"66-74","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La <span class=\"kw-ttt\">psychothérapie</span> occupe une <strong>place centrale</strong> dans la prise en charge des troubles de la personnalité.</p>\n      <p>Le type de psychothérapie dépend du trouble de la personnalité concerné ainsi que des caractéristiques individuelles du patient.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques</em></p>","frequence":0}],"astuces":[{"type":"tip","titre":"Mnémo « DEPRESSION » — critères DSM-5 de l'EDC","contenu":"<p>≥ <strong>5/9 critères pendant ≥ <span class=\"kw-chiffre\">2 semaines</span></strong>, dont au moins un parmi <strong><span class=\"kw-clinique\">humeur</span> triste</strong> ou <strong><span class=\"kw-clinique\">anhédonie</span></strong> : <strong>D</strong>épression de l'<span class=\"kw-clinique\">humeur</span> · <strong>E</strong>nergie diminuée (<span class=\"kw-clinique\">asthénie</span>) · <strong>P</strong>laisir disparu (<span class=\"kw-clinique\">anhédonie</span>) · <strong>R</strong>alentissement ou <span class=\"kw-clinique\">agitation</span> psychomoteur · <strong>E</strong>stime de soi (<span class=\"kw-clinique\">culpabilité</span>) · <strong>S</strong>ommeil perturbé · <strong>S</strong>uicide (idées de mort) · <strong>I</strong>nappétence / poids · <strong>O</strong>ublis (concentration) · <strong>N</strong>ihilisme. <span class=\"kw-alerte\">Toujours évoquer l'<span class=\"kw-def\">EDC</span></span> à la conjonction <span class=\"kw-clinique\">humeur</span> triste + <span class=\"kw-clinique\">anhédonie</span> + ≥ <span class=\"kw-chiffre\">15 jours</span>.</p>"},{"type":"warn","titre":"Piège — toujours rechercher un ATCD (hypo)maniaque avant d'introduire un AD","contenu":"<p>Un <span class=\"kw-ttt\">AD</span> en <span class=\"kw-ttt\">monothérapie</span> chez un patient <span class=\"kw-def\">bipolaire</span> ignoré peut déclencher un <strong><span class=\"kw-clinique\">virage maniaque</span></strong> ou un <strong>cycle rapide</strong>. La question « avez-vous déjà eu des périodes d'énergie exagérée, sans besoin de dormir, où vous vous sentiez puissant ou euphorique ? » doit être systématique. ATCD personnel ou familial d'épisode <span class=\"kw-clinique\">maniaque</span> → <span class=\"kw-def\">trouble bipolaire</span> jusqu'à preuve du contraire → <span class=\"kw-ttt\">thymorégulateur</span>.</p>"},{"type":"danger","titre":"Risque suicidaire à l'instauration d'un AD — fenêtre J1-J15","contenu":"<p>Les <span class=\"kw-ttt\">ISRS</span> lèvent l'inhibition motrice <strong>avant</strong> de relever l'<span class=\"kw-clinique\">humeur</span> (~<span class=\"kw-chiffre\">2 semaines</span>). Risque de <span class=\"kw-alerte\"><span class=\"kw-clinique\">passage à l'acte</span> <span class=\"kw-alerte\">suicidaire</span> majoré</span> à l'instauration, surtout chez l'adolescent et l'adulte jeune. <strong>Réévaluation à J7-J15</strong>, information du patient et de l'entourage, restriction d'accès aux moyens létaux. Préférer la <strong><span class=\"kw-ttt\">fluoxétine</span></strong> chez l'enfant/ado (seule AMM <span class=\"kw-def\">EDC</span>).</p>"},{"type":"tip","titre":"Discriminant TOC — obsessions vs idées délirantes","contenu":"<p>Dans le <span class=\"kw-def\">TOC</span>, le patient <strong>reconnaît</strong> (insight bon dans <span class=\"kw-chiffre\">75-95 %</span> des cas) le caractère absurde/excessif de ses <span class=\"kw-clinique\">pensées intrusives</span> → ego-<strong>dystoniques</strong>. Dans la <strong>schizophrénie</strong>, les idées délirantes sont <strong>ego-syntoniques</strong> avec adhésion totale et inébranlable. Insight faible (<span class=\"kw-chiffre\">5-25 %</span> des <span class=\"kw-def\">TOC</span>) = facteur pronostique péjoratif.</p>"},{"type":"warn","titre":"Piège TSPT — pas de BZD, jamais","contenu":"<p>Les <span class=\"kw-ttt\">benzodiazépines</span> dans le <span class=\"kw-def\">TSPT</span> <strong>aggravent l'évolution</strong> : interfèrent avec la consolidation du souvenir traumatique, chronicisent les symptômes, induisent <span class=\"kw-alerte\">dépendance</span>, et n'ont aucune efficacité démontrée sur les <span class=\"kw-clinique\">reviviscences</span>. Traitements de choix = <strong><span class=\"kw-ttt\">TCC</span> trauma-centrée ou <span class=\"kw-ttt\">EMDR</span></strong> + <strong><span class=\"kw-ttt\">sertraline</span>/<span class=\"kw-ttt\">paroxétine</span></strong> (seules AMM <span class=\"kw-def\">TSPT</span>). Le <strong>déni de l'événement</strong> n'est <em>pas</em> un critère diagnostique (piège récurrent d'annale).</p>"},{"type":"info","titre":"Astuce PU — durées minimales DSM-5 à mémoriser","contenu":"<p>Critère « durée » qui distingue les troubles : <strong><span class=\"kw-def\">EDC</span> ≥ <span class=\"kw-chiffre\">2 semaines</span></strong> · <strong>Trouble dépressif persistant (<span class=\"kw-clinique\">dysthymie</span>) ≥ <span class=\"kw-chiffre\">2 ans</span></strong> · <strong>Phobies / <span class=\"kw-def\">TAG</span> ≥ <span class=\"kw-chiffre\">6 mois</span></strong> · <strong>Trouble <span class=\"kw-clinique\">panique</span> ≥ <span class=\"kw-chiffre\">1 mois</span></strong> d'<span class=\"kw-clinique\">anticipation anxieuse</span> après une AP · <strong>Trouble stress aigu = <span class=\"kw-chiffre\">3 jours</span> à <span class=\"kw-chiffre\">1 mois</span></strong> · <strong><span class=\"kw-def\">TSPT</span> &gt; <span class=\"kw-chiffre\">1 mois</span></strong> · <strong>Trouble de l'adaptation : symptômes &lt; <span class=\"kw-chiffre\">3 mois</span> après le facteur de stress, durée &lt; <span class=\"kw-chiffre\">6 mois</span> après sa disparition</strong>.</p>"},{"type":"info","titre":"Discriminant TOC vs personnalité obsessionnelle-compulsive","contenu":"<p>Le <strong><span class=\"kw-def\">TOC</span></strong> = <span class=\"kw-clinique\">obsessions</span> intrusives + <span class=\"kw-clinique\">compulsions</span> ritualisées, ego-dystoniques, par crises. Le <strong>trouble de la <span class=\"kw-def\">personnalité obsessionnelle-compulsive</span></strong> (<span class=\"kw-def\">cluster C</span>) = mode <em>durable</em> de fonctionnement centré sur l'<span class=\"kw-clinique\">ordre</span>, le perfectionnisme et le contrôle, <strong>sans</strong> <span class=\"kw-clinique\">obsessions</span> ni <span class=\"kw-clinique\">compulsions</span> au sens <span class=\"kw-def\">DSM-5</span>, ego-syntonique. Coexistence possible mais entités distinctes.</p>"}],"strategie":{"urgence":"<p><strong>Urgence prioritaire :</strong> le <span class=\"kw-alerte\">risque suicidaire</span> — l'<span class=\"kw-etio\">épisode dépressif caractérisé</span> est à l'origine de <span class=\"kw-chiffre\">30 à 50 %</span> des tentatives de suicide et <span class=\"kw-chiffre\">> 80 %</span> des suicidés présentent un EDC au moment du passage à l'acte.<br><strong>1er geste :</strong> évaluer systématiquement les <span class=\"kw-clinique\">idées suicidaires</span>, la présence d'un <span class=\"kw-clinique\">plan précis</span> et les <span class=\"kw-clinique\">pensées de mort</span> chez tout patient.<br><strong>Raptus anxieux :</strong> une <span class=\"kw-alerte\">agitation anxieuse</span> (épisode mixte ou anxieux) expose à un <span class=\"kw-alerte\">passage à l'acte suicidaire</span> imprévisible.<br><strong>Attaque de panique :</strong> traitement ponctuel par <span class=\"kw-ttt\">benzodiazépine</span> (alternative <span class=\"kw-ttt\">hydroxyzine</span>) si manifestations intenses et invalidantes.</p>","hospit":"<p><strong>Ambulatoire :</strong> règle générale des <span class=\"kw-etio\">troubles anxieux</span> et <span class=\"kw-etio\">phobiques</span> ; pour un EDC suivi en ville, consultations rapprochées (<span class=\"kw-chiffre\">1×/semaine</span>).<br><strong>Hospitalisation en psychiatrie (EDC) :</strong> caractéristiques <span class=\"kw-alerte\">mélancoliques</span>, <span class=\"kw-alerte\">psychotiques</span>, <span class=\"kw-alerte\">mixtes</span> ou <span class=\"kw-alerte\">catatoniques</span> ; <span class=\"kw-alerte\">risque suicidaire élevé</span> ou de mise en danger ; formes sévères ou résistantes.<br><strong>Hospitalisation (trouble anxieux) :</strong> rare, réservée au <span class=\"kw-alerte\">risque suicidaire</span>, à une comorbidité dépressive sévère ou à des manifestations anxieuses aiguës très envahissantes.<br><strong>Recours au psychiatre :</strong> comorbidités, <span class=\"kw-ttt\">résistance à 2 antidépresseurs</span> bien conduits, situations à risque (<span class=\"kw-clinique\">grossesse</span>, <span class=\"kw-clinique\">post-partum</span>).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Idées suicidaires</span> récurrentes, <span class=\"kw-clinique\">plan précis</span> ou antécédent de tentative</li><li>Caractéristiques <span class=\"kw-alerte\">mélancoliques</span> : risque suicidaire élevé, réveils matinaux précoces, <span class=\"kw-clinique\">mutisme</span></li><li>Caractéristiques <span class=\"kw-alerte\">psychotiques</span> : idées délirantes de culpabilité/incurabilité, <span class=\"kw-etio\">syndrome de Cotard</span></li><li>Caractéristiques <span class=\"kw-alerte\">mixtes</span> (≥ 3 symptômes maniaques) : <span class=\"kw-alerte\">risque suicidaire très augmenté</span></li><li><span class=\"kw-alerte\">Raptus anxieux</span> : agitation anxieuse exposant au passage à l'acte</li><li><span class=\"kw-alerte\">Refus alimentaire</span>, dénutrition ou déshydratation : risque vital à court terme</li><li><span class=\"kw-clinique\">Symptomatologie dissociative</span> immédiate après un traumatisme (mutisme, errance, dépersonnalisation) : facteur d'évolution vers un <span class=\"kw-etio\">TSPT</span></li><li>Virage évoquant un <span class=\"kw-etio\">trouble bipolaire</span> sous antidépresseur : <span class=\"kw-clinique\">agitation</span>, <span class=\"kw-clinique\">hypomanie</span>, aggravation des symptômes</li></ul>","principes":"<p>La <span class=\"kw-ttt\">psychothérapie</span> (TCC en 1re ligne) est au socle de tous les troubles ; les <span class=\"kw-ttt\">antidépresseurs</span> (<span class=\"kw-ttt\">ISRS</span>) sont l'option pharmacologique de référence, indiquée selon la sévérité.</p><p><strong>Épisode dépressif caractérisé</strong></p><p>Durée : arrêt discuté <span class=\"kw-chiffre\">6 mois à 1 an</span> après la rémission (1er épisode isolé)</p><ul><li>1re intention : <span class=\"kw-ttt\">ISRS</span> si intensité modérée à sévère, augmentés progressivement à dose efficace</li><li>Délai d'action : <span class=\"kw-chiffre\">2 à 4 semaines</span> à dose efficace</li><li>Ne jamais <span class=\"kw-ci\">associer 2 antidépresseurs</span> ; si échec, augmenter la posologie ou changer de molécule</li><li><span class=\"kw-ttt\">Psychothérapie de soutien</span> toujours indiquée ; <span class=\"kw-ttt\">TCC</span> ou thérapie interpersonnelle structurées</li></ul><p><strong>Troubles anxieux (TAG, panique, phobie sociale)</strong></p><p><span class=\"kw-ttt\">Phobie spécifique</span> : aucun médicament efficace, prise en charge psychothérapeutique seule</p><ul><li><span class=\"kw-ttt\">TCC</span> privilégiée : relaxation, <span class=\"kw-ttt\">exposition</span> et désensibilisation</li><li>Fond : <span class=\"kw-ttt\">ISRS</span> ou <span class=\"kw-ttt\">IRSNA</span> dans les formes sévères ; durée <span class=\"kw-chiffre\">6-12 mois</span> (trouble panique)</li><li>Ponctuel : <span class=\"kw-ttt\">BZD</span> (alternative <span class=\"kw-ttt\">hydroxyzine</span>) si anxiété intense et invalidante</li><li>Trouble panique : débuter l'<span class=\"kw-ttt\">ISRS</span> à <span class=\"kw-chiffre\">doses faibles</span> car de fortes doses <span class=\"kw-alerte\">aggravent les attaques de panique</span></li></ul><p><strong>TOC</strong></p><ul><li><span class=\"kw-ttt\">TCC</span> avec exposition et prévention de la réponse = méthode de référence</li><li><span class=\"kw-ttt\">ISRS</span> à <span class=\"kw-chiffre\">posologies élevées</span> (souvent le double de celles de l'EDC)</li><li>Délai d'efficacité prolongé : <span class=\"kw-chiffre\">6 à 12 semaines</span></li><li>Anxiolytiques palliatifs : ne réduisent <span class=\"kw-ci\">ni les obsessions ni les rituels</span></li></ul><p><strong>TSPT & trouble de stress aigu</strong></p><p>PEC immédiate : <span class=\"kw-ttt\">defusing</span> / déchocage psychologique et certificat médical initial, sans faire « raconter » l'événement</p><ul><li><span class=\"kw-ttt\">Psychothérapie</span> = traitement de 1re ligne : <span class=\"kw-ttt\">TCC</span>, <span class=\"kw-ttt\">exposition prolongée</span>, <span class=\"kw-ttt\">EMDR</span></li><li><span class=\"kw-ttt\">ISRS</span> en 2e intention si symptômes sévères/chroniques ou refus de psychothérapie</li><li><span class=\"kw-ci\">Benzodiazépines à éviter</span> dans les suites d'une exposition traumatique</li></ul><p><strong>Trouble de l'adaptation</strong></p><ul><li><span class=\"kw-ttt\">Psychothérapie</span> à privilégier (verbalisation autour du facteur de stress)</li><li>Symptomatique : <span class=\"kw-ttt\">BZD</span> (alternative <span class=\"kw-ttt\">hydroxyzine</span>) si anxiété invalidante</li><li>Troubles du sommeil chez l'adulte : <span class=\"kw-ttt\">zolpidem</span> ou <span class=\"kw-ttt\">zopiclone</span></li></ul><p><strong>Traitements physiques (EDC sévère)</strong></p><ul><li><span class=\"kw-ttt\">Électroconvulsivothérapie (ECT)</span> : 1re intention si risque vital à court terme, formes <span class=\"kw-etio\">mélancoliques</span>/<span class=\"kw-etio\">catatoniques</span>/<span class=\"kw-etio\">psychotiques</span>, ou résistance médicamenteuse</li><li>Seule <span class=\"kw-ci\">contre-indication absolue de l'ECT : l'HTIC</span></li></ul>","suivi":"<p><strong>Rythme :</strong> en ambulatoire, consultations rapprochées et régulières (<span class=\"kw-chiffre\">1×/semaine</span>).<br><strong>Réévaluation :</strong> juger l'efficacité de l'<span class=\"kw-ttt\">ISRS</span> après son <span class=\"kw-chiffre\">délai d'action de 2-4 semaines</span> ; <span class=\"kw-ttt\">résistance</span> = échec de 2 antidépresseurs bien conduits (<span class=\"kw-chiffre\">≥ 6 semaines</span>).<br><strong>Risque de rechute :</strong> maximal dans les <span class=\"kw-chiffre\">6-8 mois</span> suivant l'arrêt du traitement ; <span class=\"kw-etio\">trouble dépressif récurrent</span> (dès le 3e épisode) → traitement de maintien.<br><strong>À surveiller :</strong> <span class=\"kw-clinique\">virage maniaque ou hypomaniaque</span> sous antidépresseur, persistance d'<span class=\"kw-clinique\">idées suicidaires</span>, observance et tolérance.</p>"},"liensGlobaux":[{"href":"https://www.youtube.com/watch?v=uW4Yl447z1c","label":"YouTube — Vidéo trouble dépressif/anxieux"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Symptômes anxieux, dépressifs ou réactionnels au 1er plan — Cause non psychiatrique et prise de substance éliminées","detail":"<h4>CAT — Orientation devant des symptômes anxieux ou dépressifs — Item 66 : démarche diagnostique et conduite à tenir, après élimination d'une cause non psychiatrique et d'une prise de substance</h4>","branches":[{"to":"t-hospit","label":"Risque suicidaire / mélancolie / psychose / mise en danger","color":"red"},{"to":"q-react","label":"Absence de signe de gravité immédiat","color":"blue"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation en psychiatrie + mise en sécurité — Risque suicidaire ou caractéristiques de gravité","color":"red","detail":"<h4>Conduite</h4><ul><li>Hospitalisation en <span class=\"kw-ttt\">psychiatrie</span>, au besoin sous contrainte</li><li>Protection vis-à-vis du <span class=\"kw-alerte\">risque suicidaire</span> et de la mise en danger</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antidépresseur</span> ± <span class=\"kw-ttt\">antipsychotique</span> si caractéristiques psychotiques</li><li><span class=\"kw-ttt\">ECT</span> en 1re intention si risque vital à court terme (TS, dénutrition, déshydratation)</li></ul>"},{"id":"q-react","kind":"decision","label":"Symptômes réactionnels à un événement ou facteur de stress identifiable ?","branches":[{"to":"q-trauma","label":"Oui · réactionnel à un événement","color":"blue"},{"to":"q-anxieux","label":"Non · trouble anxieux primaire","color":"blue"}]},{"id":"q-trauma","kind":"decision","label":"Événement objectivement traumatisant et délai des symptômes ? — Traumatisant = menace de mort, blessure grave, violence sexuelle","branches":[{"to":"t-adapt","label":"Stress non traumatisant","color":"amber"},{"to":"t-tsa","label":"Traumatisant · < 1 mois","color":"amber"},{"to":"t-tspt","label":"Traumatisant · > 1 mois","color":"amber"}]},{"id":"t-adapt","kind":"terminal","label":"Trouble de l'adaptation — Réaction excessive à un stress non traumatisant","color":"amber","detail":"<h4>Clinique</h4><ul><li>Symptômes < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">3 mois</span></span> après le stress, résolutifs < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">6 mois</span></span> après son arrêt</li><li>Pas de syndrome de répétition ni d'évitement</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Psychothérapie</span> ; <span class=\"kw-ttt\">BZD</span>/<span class=\"kw-ttt\">hydroxyzine</span> ou <span class=\"kw-ttt\">zolpidem</span>/<span class=\"kw-ttt\">zopiclone</span> à visée symptomatique</li></ul><h4>Surveillance</h4><ul><li><span class=\"kw-alerte\">Risque suicidaire</span> : <span class=\"kw-chiffre\">2-4 %</span> de tentatives, jusqu'à <span class=\"kw-chiffre\">10 %</span> chez l'adolescent</li></ul>"},{"id":"t-tsa","kind":"terminal","label":"Trouble de stress aigu — Symptômes < 1 mois après le traumatisme","color":"amber","detail":"<h4>Clinique</h4><ul><li>Symptomatologie proche du TSPT mais durée <span class=\"kw-chiffre\">3 jours à 1 mois</span></li><li>Évolution souvent <span class=\"kw-clinique\">spontanément résolutive</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Psychothérapie</span> ; <span class=\"kw-ci\">éviter les benzodiazépines</span></li></ul><h4>Surveillance</h4><ul><li>Risque d'évolution vers un <span class=\"kw-etio\">TSPT</span> (ATCD psychiatriques, symptômes dissociatifs initiaux)</li></ul>"},{"id":"t-tspt","kind":"terminal","label":"Trouble de stress post-traumatique — Symptômes > 1 mois","color":"amber","detail":"<h4>Clinique</h4><ul><li>Syndrome de <span class=\"kw-clinique\">répétition</span>, syndrome d'<span class=\"kw-clinique\">évitement</span> et <span class=\"kw-clinique\">hyperactivation neurovégétative</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Psychothérapie</span> de 1re ligne : <span class=\"kw-ttt\">TCC</span>, <span class=\"kw-ttt\">EMDR</span>, exposition prolongée</li><li><span class=\"kw-ttt\">ISRS</span> en 2e intention ; <span class=\"kw-ci\">BZD à éviter</span></li></ul><h4>Surveillance</h4><ul><li><span class=\"kw-alerte\">Risque suicidaire</span> augmenté ; dépister un <span class=\"kw-etio\">EDC</span> associé</li></ul>"},{"id":"q-anxieux","kind":"decision","label":"Symptôme anxieux prédominant ?","branches":[{"to":"t-phobie","label":"Évitement d'un objet/situation","color":"green"},{"to":"t-toc","label":"Obsessions / compulsions","color":"amber"},{"to":"t-panique","label":"Attaques de panique récurrentes","color":"amber"},{"to":"t-tag","label":"Inquiétudes multiples > 6 mois","color":"green"}]},{"id":"t-phobie","kind":"terminal","label":"Trouble phobique — Évitement d'un objet ou d'une situation défini","color":"green","detail":"<h4>Conduite</h4><ul><li>Prise en charge <span class=\"kw-ttt\">ambulatoire</span>, psychothérapeutique en 1er lieu</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">TCC</span> : restructuration cognitive + <span class=\"kw-ttt\">exposition graduée</span></li><li><span class=\"kw-ttt\">ISRS/IRSNA</span> si phobie sociale sévère ; <span class=\"kw-ci\">aucun médicament efficace</span> dans la phobie spécifique</li></ul>"},{"id":"t-toc","kind":"terminal","label":"Trouble obsessionnel compulsif — Obsessions et/ou compulsions","color":"amber","detail":"<h4>Clinique</h4><ul><li>Obsessions (pensées intrusives) ± compulsions/rituels, perte de temps > <span class=\"kw-chiffre\">1 h/jour</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">TCC</span> avec exposition et prévention de la réponse</li><li><span class=\"kw-ttt\">ISRS</span> à <span class=\"kw-chiffre\">posologies élevées</span>, délai d'efficacité <span class=\"kw-chiffre\">6-12 semaines</span></li></ul>"},{"id":"t-panique","kind":"terminal","label":"Trouble panique ± agoraphobie — Attaques de panique récurrentes et inattendues","color":"amber","detail":"<h4>Clinique</h4><ul><li>Répétition d'<span class=\"kw-clinique\">attaques de panique</span> + <span class=\"kw-clinique\">anxiété anticipatoire</span> (« peur d'avoir peur »)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">TCC</span> (exposition aux sensations) ; <span class=\"kw-ttt\">ISRS</span> de fond débuté à <span class=\"kw-chiffre\">doses faibles</span></li><li><span class=\"kw-ttt\">BZD</span> ponctuelle si crise invalidante</li></ul><h4>Surveillance</h4><ul><li>Trouble anxieux au <span class=\"kw-alerte\">plus haut risque d'EDC</span></li></ul>"},{"id":"t-tag","kind":"terminal","label":"Trouble anxiété généralisée — Inquiétudes multiples et mal contrôlées > 6 mois","color":"green","detail":"<h4>Clinique</h4><ul><li>Soucis excessifs sur ≥ 2 thèmes, <span class=\"kw-chiffre\">> 6 mois</span> ; insomnie souvent au 1er plan</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">TCC</span> + règles hygiéno-diététiques (arrêt des excitants)</li><li><span class=\"kw-ttt\">ISRS</span>/<span class=\"kw-ttt\">IRSNA</span> de fond si forme sévère ; <span class=\"kw-ttt\">BZD</span> ponctuelle</li></ul>"}]},"cards":[{"i":"0735dc9f65f5","n":66,"o":"66-14","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Dans le cadre d'un État Dépressif Caractérisé (EDC), quand doit-on indiquer un recours au psychiatre devant une comorbidité ?","a":"<p>Un recours au psychiatre est indiqué devant un EDC en présence de <strong>comorbidités psychiatriques ou non psychiatriques</strong> associées.</p>"},{"i":"22b792b98630","n":66,"o":"66-14","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Concernant un État Dépressif Caractérisé (EDC), quelle est l'indication du recours au psychiatre liée à la réponse au traitement antidépresseur ?","a":"<p>Un recours au psychiatre est nécessaire en cas de <strong>résistance à deux antidépresseurs</strong> (AD) bien conduits, c'est-à-dire prescrits à une posologie et une durée suffisantes.</p>"},{"i":"933a45694e20","n":66,"o":"66-14","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Quelles sont les situations cliniques à risque ou les caractéristiques particulières d'un État Dépressif Caractérisé (EDC) justifiant un recours au psychiatre ?","a":"<p>Le recours au psychiatre est indiqué dans les situations à risque suivantes :</p><ul><li>La <strong>grossesse</strong>.</li><li>Le <strong>post-partum</strong>.</li></ul><p>Il est également indiqué en cas de <strong>caractéristiques cliniques particulières</strong>, ou de <strong>doute sur un trouble bipolaire</strong>.</p>"},{"i":"56d3ee00d440","n":66,"o":"66-28","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Dans le cadre d'un trouble anxieux, quand doit-on indiquer un recours au psychiatre en cas de sévérité du trouble ?","a":"<p>Un recours au psychiatre est indiqué pour un trouble anxieux si le trouble est <strong>sévère</strong>.</p>"},{"i":"a550530c31c1","n":66,"o":"66-28","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Quand un trouble anxieux, résistant à la prise en charge initiale, justifie-t-il un recours au psychiatre ?","a":"<p>Un recours au psychiatre est indiqué pour un trouble anxieux si le trouble présente une <strong>résistance au traitement</strong> initial.</p>"},{"i":"cd7cb46670fd","n":66,"o":"66-28","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Quelles situations de comorbidité chez un patient présentant un trouble anxieux justifient-elles une consultation psychiatrique ?","a":"<p>Un recours au psychiatre est indiqué si le trouble anxieux est associé à une <strong>comorbidité psychiatrique</strong> ou <strong>non psychiatrique</strong>.</p>"},{"i":"e4f33648f9b2","n":66,"o":"66-28","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Quelles situations à risque spécifiques imposent-elles un recours au psychiatre en présence d'un trouble anxieux ?","a":"<p>Un recours au psychiatre est indiqué si le trouble anxieux survient dans une <strong>situation à risque spécifique</strong>, notamment la <strong>grossesse</strong> ou le <strong>post-partum</strong>.</p>"},{"i":"05763190686b","n":66,"o":"66-30","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique","q":"Comment définir une attaque de panique ?","a":"<p>L'attaque de panique est une crise spontanée et imprévisible, centrale dans le trouble panique. Elle se manifeste par une anxiété intense, devient secondairement liée à une anxiété anticipatoire et aux situations redoutées (agoraphobie). Sa durée moyenne est de <strong>20 à 30 minutes</strong> et elle est <strong>spontanément résolutive</strong>.</p>"},{"i":"0f187a1c8791","n":66,"o":"66-30","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique","q":"Quelle est la prise en charge à distance d'une attaque de panique dans le cadre d'un trouble panique ?","a":"<p>La prise en charge à distance du trouble panique repose sur une <strong>psychothérapie</strong> (notamment les <strong>TCC</strong> avec exposition aux sensations physiques des attaques de panique) et un traitement de fond par <strong>ISRS</strong> (à doses faibles au départ) dans les formes sévères. Pour une attaque de panique isolée, l'accent est mis sur l'information et l'éducation thérapeutique pour reconnaître une récidive et appliquer des règles hygiéno-diététiques.</p>"},{"i":"3d34b6d77036","n":66,"o":"66-30","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique","q":"Quel traitement pharmacologique peut être proposé en urgence lors d'une attaque de panique prolongée et sévère ?","a":"<p>En cas d'attaque de panique prolongée et sévère, une <strong>benzodiazépine</strong> peut être administrée par <strong>voie orale</strong>. Il s'agit d'un traitement <strong>ponctuel uniquement</strong>, sans aucun intérêt au long cours en raison du risque de dépendance.</p>"},{"i":"a04e4dc634dc","n":66,"o":"66-30","u":"Prise en charge","t":"Connaître la prise en charge de l’attaque de panique","q":"Quelle est la prise en charge non pharmacologique d'une attaque de panique en urgence ?","a":"<ul><li><strong>Mise en condition</strong>: installation au calme, suppression des éléments anxiogènes, attitude empathique.</li><li><strong>Réassurance</strong>: donner un diagnostic positif (« il s’agit d’une attaque de panique »), informer de l'absence de danger de mort et du caractère spontanément résolutif de la crise.</li><li><strong>Contrôle ventilatoire</strong>: allongement du temps d’expiration (idéalement <strong>à lèvres pincées</strong>) pour stimuler le tonus vagal, focaliser l’attention et limiter l’hyperventilation.</li><li><strong>Éliminer une urgence non psychiatrique</strong>, une intoxication ou un sevrage, et écarter un facteur déclenchant.</li></ul>"},{"i":"67e2a8531cfb","n":66,"o":"66-34","u":"Définition","t":"Connaître la définition des obsessions, des compulsions, des troubles obsessionnels compulsifs","q":"Quelle est la définition des compulsions dans le cadre d'un trouble obsessionnel compulsif (TOC) ?","a":"<p>Les compulsions sont des <stong>comportements répétitifs</stong> (ex : se laver, ordonner, vérifier) ou des <stong>actes mentaux</stong> (ex : compter, répéter) que le patient se sent <stong>forcé d'accomplir</stong> en réponse à une obsession ou selon des règles inflexibles. Leur objectif est de <stong>neutraliser l'anxiété</stong> engendrée par l'obsession, et elles ne sont pas sources de plaisir.</p>"},{"i":"87bf83310a13","n":66,"o":"66-34","u":"Définition","t":"Connaître la définition des obsessions, des compulsions, des troubles obsessionnels compulsifs","q":"Comment définit-on un trouble obsessionnel compulsif (TOC) ?","a":"<p>Le trouble obsessionnel compulsif (TOC) se définit par la présence d'une ou plusieurs <stong>obsessions</stong> et/ou d'une ou plusieurs <stong>compulsions</stong>. Le diagnostic peut être posé en présence d'obsessions seules, de compulsions seules, ou des deux.</p>"},{"i":"c53b5d9dd6c4","n":66,"o":"66-34","u":"Définition","t":"Connaître la définition des obsessions, des compulsions, des troubles obsessionnels compulsifs","q":"Quelle est la définition des obsessions dans le cadre d'un trouble obsessionnel compulsif (TOC) ?","a":"<p>Les obsessions sont des pensées, pulsions ou images qui <stong>irrompent de manière intrusive</stong>, sont <stong>récurrentes et persistantes</stong>. Elles sont perçues comme <stong>égo-dystoniques</stong> (en désaccord avec la pensée consciente, jugées inappropriées) et génèrent une forte <stong>anxiété</stong>.</p>"},{"i":"0a06a5bfdef2","n":66,"o":"66-36","u":"Étiologie","t":"Savoir que l’étiologie est multifactorielle","q":"Quelle est la nature de l'étiologie du Trouble Obsessionnel Compulsif (TOC) ?","a":"<p>L'étiologie du Trouble Obsessionnel Compulsif (TOC) est de nature <strong>multifactorielle</strong>.</p>"},{"i":"a9032904c713","n":66,"o":"66-36","u":"Étiologie","t":"Savoir que l’étiologie est multifactorielle","q":"Quels sont les facteurs génétiques impliqués dans l'étiologie du Trouble Obsessionnel Compulsif (TOC) ?","a":"<p>La vulnérabilité génétique au Trouble Obsessionnel Compulsif (TOC) implique des <strong>gènes codant pour des protéines des systèmes sérotoninergique et dopaminergique</strong>.</p>"},{"i":"de257b378679","n":66,"o":"66-36","u":"Étiologie","t":"Savoir que l’étiologie est multifactorielle","q":"Quelle est la part des facteurs environnementaux dans l'étiologie du Trouble Obsessionnel Compulsif (TOC) ?","a":"<p>Les facteurs environnementaux potentiellement impliqués dans l'étiologie du Trouble Obsessionnel Compulsif (TOC) sont <strong>extrêmement mal connus</strong> à ce jour.</p>"},{"i":"368541e43a2b","n":66,"o":"66-37","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelle est la distinction-clé entre une impulsion et une compulsion ?","a":"<ul><li>Une <strong>impulsion</strong> est un acte <strong>insuffisamment réfléchi</strong>, sans prise en compte des conséquences.</li><li>Une <strong>compulsion</strong> est une action <strong>longuement réfléchie</strong> qui vise à diminuer l'anxiété liée à une obsession.</li></ul>"},{"i":"69aff0c76787","n":66,"o":"66-37","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Comment définit-on une obsession dans le cadre du trouble obsessionnel compulsif (TOC) ?","a":"<p>Une obsession est une <strong>idée, une pensée ou une image récurrente et persistante</strong>, vécue comme intrusive et inappropriée, provoquant une anxiété ou une détresse importante chez le patient.</p>"},{"i":"dde1f67e574c","n":66,"o":"66-37","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelle est la particularité de l'insight chez les patients atteints de TOC et son intérêt pronostique ?","a":"<p>L'insight (ou conscience du trouble) est <strong>variable</strong> chez les patients TOC. La majorité des patients ont un bon insight, mais <strong>5 à 25 %</strong> ont un <strong>insight faible</strong>. Un insight faible est un <strong>facteur pronostique péjoratif</strong> de l'évolution à long terme du trouble.</p>"},{"i":"effe6cc2c406","n":66,"o":"66-37","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quels sont les principaux thèmes obsessionnels-compulsifs décrits ?","a":"<ul><li><strong>Contamination</strong> (obsessions de contamination, rituels de lavage ou d'évitement)</li><li><strong>Erreur, Ordre, Symétrie</strong> (obsessions d'exactitude, pensées magiques, rituels de vérification, d'alignement)</li><li><strong>Pensées interdites</strong> (catastrophe, impulsion agressive, thématiques sexuelles/religieuses/somatiques, rituels de vérification, de prières ou rituels mentaux)</li><li><strong>Accumulation</strong> (peur de perdre un objet, accumulation compulsive ou <strong>syllogomanie</strong>)</li></ul>"},{"i":"fc74f2c785bf","n":66,"o":"66-37","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Comment définit-on une compulsion dans le cadre du trouble obsessionnel compulsif (TOC) ?","a":"<p>Une compulsion est un <strong>comportement répétitif</strong> (ex: lavage, vérification) ou un <strong>acte mental</strong> (ex: prière, comptage) que le patient se sent obligé d'accomplir en réponse à une obsession, selon certaines règles, dans le but de <strong>diminuer l'anxiété</strong> ou de prévenir un événement redouté.</p>"},{"i":"1eee8c4c050b","n":66,"o":"66-47","u":"Définition","t":"Connaître la définition d’un événement potentiellement traumatique, d’un trouble stress aigu, d’un trouble stress post-traumatique, des symptômes dissociatifs","q":"Quels sont les symptômes dissociatifs et leurs manifestations principales ?","a":"<p>Les symptômes dissociatifs sont une <strong>altération de la perception</strong> de la réalité, de l'environnement ou de soi-même. Ils se manifestent principalement par :</p><ul><li>La <strong>dépersonnalisation</strong> (sentiment d'être détaché de son propre corps ou de son processus mental)</li><li>La <strong>déréalisation</strong> (sentiment d'irréalité du monde extérieur)</li><li>L'<strong>amnésie de l'événement</strong> (incapacité à se rappeler des aspects importants du traumatisme)</li></ul>"},{"i":"25a85a12615f","n":66,"o":"66-47","u":"Définition","t":"Connaître la définition d’un événement potentiellement traumatique, d’un trouble stress aigu, d’un trouble stress post-traumatique, des symptômes dissociatifs","q":"Quelle est la définition du trouble stress aigu (TSA) et sa principale caractéristique temporelle ?","a":"<p>Le trouble stress aigu (TSA) présente une symptomatologie <strong>similaire au trouble stress post-traumatique (TSPT)</strong>. Il débute dans les jours suivant l'événement traumatique et sa durée est <strong>inférieure ou égale à 1 mois</strong>.</p>"},{"i":"2c53ede580f3","n":66,"o":"66-47","u":"Définition","t":"Connaître la définition d’un événement potentiellement traumatique, d’un trouble stress aigu, d’un trouble stress post-traumatique, des symptômes dissociatifs","q":"Comment définit-on le trouble stress post-traumatique (TSPT) et quel est son critère temporel essentiel ?","a":"<p>Le trouble stress post-traumatique (TSPT) est caractérisé par la survenue de <strong>symptômes spécifiques</strong> suite à l'exposition à un événement potentiellement traumatique. La persistance de ces symptômes doit être <strong>supérieure à 1 mois</strong>.</p>"},{"i":"4f308cb60663","n":66,"o":"66-47","u":"Définition","t":"Connaître la définition d’un événement potentiellement traumatique, d’un trouble stress aigu, d’un trouble stress post-traumatique, des symptômes dissociatifs","q":"Qu'est-ce qu'un événement potentiellement traumatique (ET) selon les critères diagnostiques ?","a":"<p>Un événement potentiellement traumatique est une situation où l'on a été <strong>menacé de mort</strong>, a <strong>trouvé la mort</strong>, a subi des <strong>blessures graves</strong> ou des <strong>violences sexuelles</strong>. Les modes d'exposition incluent être victime directe, témoin direct, apprendre qu'un ET est arrivé à un proche, ou une exposition répétée dans un cadre professionnel (pompiers, soignants, policiers).</p>"},{"i":"22ddf7d2053a","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelles sont les quatre grandes familles de symptômes associées au Trouble de Stress Post-Traumatique (TSPT) après l'exposition à un événement traumatique (ET) ?","a":"Les quatre grandes familles de symptômes du TSPT sont :\n<ul>\n<li>Le <strong>syndrome de répétition</strong>.</li>\n<li>Le <strong>syndrome d'évitement</strong>.</li>\n<li>L'<strong>hyperactivation neurovégétative</strong>.</li>\n<li>Les <strong>altérations négatives des cognitions et de l'humeur</strong>.</li>\n</ul>"},{"i":"44e2f5dba8d4","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quels sont les signes d'hyperactivation neurovégétative observés dans le Trouble de Stress Post-Traumatique (TSPT) ?","a":"L'hyperactivation neurovégétative dans le TSPT se caractérise par :\n<ul>\n<li>Des <strong>altérations du sommeil</strong>, souvent au premier plan.</li>\n<li>Une <strong>irritabilité</strong> ou des <strong>accès de colère</strong>.</li>\n<li>Une <strong>hypervigilance</strong> avec des réactions de sursaut exagérées.</li>\n<li>Des <strong>troubles de la concentration</strong> et de la mémoire.</li>\n</ul>"},{"i":"63444ceac961","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelles sont les caractéristiques du syndrome de répétition dans le cadre du Trouble de Stress Post-Traumatique (TSPT) ?","a":"Le syndrome de répétition du TSPT se manifeste par des <strong>reviviscences involontaires, vivaces et envahissantes</strong> de l'événement traumatique, des <strong>cauchemars traumatiques</strong>, des <strong>réactions dissociatives</strong> (notamment des <strong>flash-backs</strong> d'une durée de quelques secondes à minutes) et une <strong>détresse psychique intense</strong> lors de l'exposition à des stimuli évoquant l'événement traumatique (ET)."},{"i":"a17543958038","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Est-ce que le déni de l'événement traumatique est un symptôme évocateur de Trouble de Stress Post-Traumatique (TSPT) ?","a":"Non, le <strong>déni de l'événement traumatique n'est PAS évocateur de TSPT</strong>."},{"i":"ad5d926bd37d","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelles sont les altérations négatives des cognitions et de l'humeur spécifiques au Trouble de Stress Post-Traumatique (TSPT) ?","a":"Les altérations négatives des cognitions et de l'humeur dans le TSPT incluent des <strong>distorsions cognitives persistantes</strong> concernant soi-même et autrui, une <strong>incapacité d'éprouver des émotions positives</strong>, un <strong>sentiment de détachement</strong> et une <strong>diminution marquée des intérêts</strong>."},{"i":"e789868f0d2a","n":66,"o":"66-50","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Comment se manifeste le syndrome d'évitement dans le Trouble de Stress Post-Traumatique (TSPT) ?","a":"Le syndrome d'évitement dans le TSPT se caractérise par l'<strong>évitement actif</strong> des <strong>rappels externes</strong> (personnes, lieux, situations) et des <strong>rappels internes</strong> (souvenirs, pensées, sentiments) liés à l'événement traumatique (ET)."},{"i":"35eedb8a4252","n":66,"o":"66-53","u":"Prise en charge","t":"Connaître les principaux généraux de la prise en charge immédiate au décours d’un événement potentiellement traumatique","q":"Quelles sont les modalités médicales recommandées dans la prise en charge immédiate d'un événement potentiellement traumatique ?","a":"Les techniques de <strong>defusing</strong> (ou « déchocage psychologique ») sont recommandées. Elles visent à <strong>réduire la charge émotionnelle</strong> et à <strong>identifier les personnes vulnérables</strong>, sans pour autant demander à la personne de raconter l'événement."},{"i":"c378423b8468","n":66,"o":"66-53","u":"Prise en charge","t":"Connaître les principaux généraux de la prise en charge immédiate au décours d’un événement potentiellement traumatique","q":"Quels sont les pièges à éviter dans la prise en charge immédiate après un événement potentiellement traumatique ?","a":"Deux pièges principaux sont à éviter :\n<ul>\n  <li>L'utilisation de <strong>benzodiazépines est à éviter</strong> dans les suites d'une exposition traumatique.</li>\n  <li>Il faut savoir que les interventions précoces ne suffisent pas à elles seules à éviter le développement d'un <strong>Trouble de Stress Post-Traumatique (TSPT)</strong> ou d'un <strong>Trouble de Stress Aigu (TSA)</strong>.</li>\n</ul>"},{"i":"d7ad8ba12295","n":66,"o":"66-53","u":"Prise en charge","t":"Connaître les principaux généraux de la prise en charge immédiate au décours d’un événement potentiellement traumatique","q":"Quelles sont les modalités juridiques et sociales à mettre en place immédiatement suite à un événement potentiellement traumatique ?","a":"Sur le plan juridique :\n<ul>\n  <li>Un <strong>certificat médical initial</strong> systématique doit être établi.</li>\n  <li>Des <strong>prélèvements</strong> sont à proposer en cas d'agression sexuelle.</li>\n</ul>\nSur le plan social, une <strong>orientation vers des associations spécialisées</strong> ou des <strong>groupes d'entraide</strong> est préconisée."},{"i":"deaaf4dbb222","n":66,"o":"66-53","u":"Prise en charge","t":"Connaître les principaux généraux de la prise en charge immédiate au décours d’un événement potentiellement traumatique","q":"Quels sont les objectifs généraux de la prise en charge immédiate au décours d'un événement potentiellement traumatique ?","a":"Les objectifs incluent :\n<ul>\n  <li>Repérer et traiter les <strong>manifestations aiguës de stress</strong> (notamment la <strong>symptomatologie dissociative</strong>).</li>\n  <li>Mettre à disposition une <strong>aide psychologique</strong>.</li>\n  <li><strong>Informer</strong> les victimes et leurs proches.</li>\n</ul>"},{"i":"346ad988e48b","n":66,"o":"66-57","u":"Définition","t":"Connaître la définition du stress et de l’adaptation au stress, des troubles de l’adaptation","q":"Décrivez la physiopathologie initiale du stress conduisant potentiellement à un trouble de l'adaptation.","a":"<p>Après un événement stressant, la réaction initiale est un <strong>choc</strong>, caractérisé par la coexistence d'un <strong>déni</strong> et d'une <strong>sidération</strong>. Des capacités d'adaptation, influencées par des facteurs génétiques et environnementaux, se mettent ensuite en place.</p>"},{"i":"5a4639d6da18","n":66,"o":"66-57","u":"Définition","t":"Connaître la définition du stress et de l’adaptation au stress, des troubles de l’adaptation","q":"Quelle est la définition du trouble de l'adaptation ?","a":"<p>Le trouble de l'adaptation est caractérisé par des symptômes réactionnels survenant après un ou plusieurs <strong>événements de vie stressants</strong>, auxquels le sujet n'arrive pas à s'adapter. Ces symptômes sont jugés <strong>excessifs</strong> par rapport à ce qui serait attendu pour un événement similaire et les capacités d'adaptation du patient sont dépassées.</p>"},{"i":"8fda6cc0e4dd","n":66,"o":"66-57","u":"Définition","t":"Connaître la définition du stress et de l’adaptation au stress, des troubles de l’adaptation","q":"Comment différencier un trouble de l'adaptation d'un autre trouble psychiatrique ?","a":"<p>Les symptômes du trouble de l'adaptation ne doivent <strong>pas remplir les critères diagnostiques</strong> d'un trouble de l'humeur, d'un trouble anxieux ou d'un autre trouble mental spécifique.</p>"},{"i":"4a6d89195e55","n":66,"o":"66-58","u":"Epidémiologie","t":"Connaître la prévalence","q":"Quelle est la fréquence de consultation pour un trouble de l'adaptation en médecine générale ?","a":"<p>Le trouble de l'adaptation représente <strong>10 à 20 %</strong> des motifs de consultation en médecine générale.</p>"},{"i":"87d290696b50","n":66,"o":"66-58","u":"Epidémiologie","t":"Connaître la prévalence","q":"Quelle est la prévalence du trouble de l'adaptation dans la population générale ?","a":"<p>La prévalence du trouble de l'adaptation est d'environ <strong>10 %</strong> dans la population générale.</p>"},{"i":"e1e718a61a71","n":66,"o":"66-58","u":"Epidémiologie","t":"Connaître la prévalence","q":"Quelle est la fréquence de consultation pour un trouble de l'adaptation en psychiatrie ambulatoire ?","a":"<p>Le trouble de l'adaptation représente <strong>5 à 20 %</strong> des motifs de consultation en psychiatrie ambulatoire.</p>"},{"i":"035a7f9f1aaf","n":66,"o":"66-60","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quels sont les critères temporels (délai d'apparition et durée) pour le diagnostic d'un trouble de l'adaptation ?","a":"<p>Pour le diagnostic d'un trouble de l'adaptation :</p><ul><li>Le <strong>délai d’apparition</strong> des manifestations doit être au plus tard dans les <strong>< 3 mois</strong> suivant le début du facteur de stress.</li><li>La <strong>durée</strong> des symptômes doit être inférieure à <strong>6 mois</strong> après l’arrêt du facteur de stress.</li></ul>"},{"i":"2c2cf5f1aef5","n":66,"o":"66-60","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quel est le piège classique concernant le diagnostic différentiel du trouble de l'adaptation ?","a":"<p>Le piège classique est de considérer les troubles liés au <strong>deuil</strong> comme des troubles de l'adaptation. En réalité, ils n’en font pas partie et sont regroupés dans les <strong>deuils pathologiques</strong>.</p>"},{"i":"98d0a7b5d551","n":66,"o":"66-60","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quels types d'événements stressants peuvent déclencher un trouble de l'adaptation ?","a":"<p>Les événements stressants déclencheurs d'un trouble de l'adaptation incluent généralement les <strong>changements imposant une adaptation</strong> dans les domaines professionnel et/ou personnel, tels que :</p><ul><li>Une <strong>annonce diagnostique d’une pathologie grave</strong>.</li><li>Des <strong>transitions de vie</strong> (mariage, rupture, changement de métier, difficultés financières).</li></ul><p>Des événements d’apparence non stressante peuvent également suffire chez les personnes vulnérables.</p>"},{"i":"a07823adab6b","n":66,"o":"66-60","u":"Diagnostic positif","t":"Connaître la sémiologie","q":"Quelles sont les manifestations cliniques des troubles de l'adaptation ?","a":"<p>Les troubles de l'adaptation se manifestent par des <strong>symptômes émotionnels ou comportementaux</strong>. Ces manifestations ne remplissent pas les critères d’un autre trouble psychiatrique. Leur caractère pathologique est défini par une <strong>altération du fonctionnement socio-professionnel</strong>.</p>"},{"i":"7309a3e38eeb","n":66,"o":"66-65","u":"Prise en charge","t":"Connaître les indications du recours au psychiatre","q":"Dans quels cas un trouble de l'adaptation justifie-t-il un recours au psychiatre ?","a":"<p>Un trouble de l'adaptation justifie un recours au psychiatre dans les situations suivantes :</p><ul><li>Lorsqu'il s'agit d'un <strong>trouble sévère</strong>.</li><li>En cas de <strong>résistance au traitement</strong>.</li><li>En présence d'une <strong>comorbidité psychiatrique ou non psychiatrique</strong>.</li><li>Face à une <strong>situation à risque spécifique</strong> (par exemple, grossesse, post-partum).</li></ul>"},{"i":"120c9e937ae8","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Quels sont les signes caractéristiques du trouble de la personnalité borderline (Cluster B) ?","a":"<p>Les signes caractéristiques du trouble de la personnalité borderline sont une <strong>instabilité de l'identité</strong>, une <strong>instabilité affective</strong> (avec un sentiment chronique de vide), et une <strong>instabilité interpersonnelle</strong> alternant entre idéalisation et rejet, et une peur intense de l'abandon. On observe également une <strong>impulsivité marquée</strong> (notamment des auto-mutilations et des tentatives de suicide répétées), ainsi que des symptômes psychotiques ou dissociatifs transitoires. Le risque suicidaire est élevé, de l'ordre de <strong>8-10%</strong>.</p>"},{"i":"2ed5f9b3ed83","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Quels sont les éléments sémiologiques des troubles de la personnalité du Cluster B, caractérisés par une tendance émotionnelle ?","a":"<ul><li><strong>Trouble Antisocial</strong> : <strong>impulsivité</strong>, passages à l'acte, transgressions répétées des droits d'autrui, <strong>absence de culpabilité</strong> et manipulation. La biographie est marquée par l'instabilité et un trouble des conduites avant 15 ans.</li><li><strong>Trouble Histrionique</strong> : <strong>labilité émotionnelle</strong>, hyperexpressivité, <strong>théâtralisme</strong>, suggestibilité, quête affective excessive et attitude séductrice. Les tentatives de suicide sont fréquentes.</li><li><strong>Trouble Narcissique</strong> : sens grandiose de sa propre importance, faible tolérance à la critique, <strong>manque d'empathie</strong> et estime de soi fragile malgré les apparences.</li></ul>"},{"i":"31767a293a1d","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Quels sont les éléments sémiologiques des troubles de la personnalité du Cluster C, caractérisés par une tendance anxieuse ?","a":"<ul><li><strong>Trouble Évitant</strong> : <strong>Inhibition relationnelle</strong>, mésestime de soi, <strong>hypersensibilité au jugement négatif</strong> et conduites d'évitement social. Le diagnostic différentiel inclut la phobie sociale.</li><li><strong>Trouble Dépendant</strong> : Besoin excessif d'être pris en charge, dévalorisation, incapacité à s'affirmer ou à exprimer un désaccord.</li></ul>"},{"i":"94f1b53e8555","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Quels sont les éléments sémiologiques des troubles de la personnalité du Cluster A, caractérisés par une tendance psychotique ?","a":"<ul><li><strong>Trouble Schizoïde</strong> : Tendance à l'<strong>isolement</strong>, absence d'intérêt pour autrui, <strong>froideur</strong> et réactivité émotionnelle peu marquée. Il peut précéder une schizophrénie.</li><li><strong>Trouble Schizotypique</strong> : Croyances bizarres, <strong>distorsions cognitives</strong>, champs d'intérêt originaux, compétences sociales altérées, et affects pauvres ou inadéquats. Il peut également précéder une schizophrénie.</li></ul>"},{"i":"de225c67001f","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Quelle est la sémiologie du trouble de la personnalité paranoïaque (Cluster A) ?","a":"<p>La sémiologie du trouble de la personnalité paranoïaque inclut une <strong>rigidité psychique</strong>, une très faible expression émotionnelle et une <strong>méfiance généralisée envers autrui</strong>. Elle s'accompagne souvent d'une altération du jugement et peut se compliquer d'un trouble délirant persistant.</p>"},{"i":"e2c9fe763af2","n":66,"o":"66-73","u":"Diagnostic","t":"Connaître la sémiologie","q":"Comment se manifeste le trouble de la personnalité obsessionnelle-compulsive (Cluster C) ?","a":"<p>Le trouble de la personnalité obsessionnelle-compulsive se manifeste par une <strong>méticulosité</strong>, un souci excessif du <strong>détail et de l'ordre</strong>, une <strong>rigidité</strong> et un <strong>perfectionnisme</strong>. Les émotions sont exprimées avec un contrôle important. Il est important de noter qu'il n'y a <strong>pas d'obsession ni de compulsion</strong> au sens du trouble obsessionnel-compulsif (TOC).</p>"}]};